import type { MeaningPack } from '../../types';

export const taSmvVerses1: MeaningPack = {
  lang: 'ta',
  texts: {
    'sumadhva-vijaya-01': {
      verses: {
        '0.0': 'அழகனும், மங்கள குணங்களுக்கு ஒரே இருப்பிடமும், உதிக்கும் சூரியனைப் போல் ஒளிர்பவனும், அனைத்திற்கும் காரணனும், ஸ்ரீதேவிக்கும் பிராணதேவருக்கும் (வாயுவுக்கும்) நாதனுமான நாராயணனை வணங்குகிறேன்.',
        '0.1': 'எவரால் காக்கப்பட்ட கோகுலம் எப்போதும் கலக்கமின்றி தூய உள்ளத்துடன் விளங்கியதோ, கார்மேகம் போல் நீல நிறம் கொண்டவனும், கிருஷ்ணையின் (திரௌபதியின்) கணவனான பீமனுக்கு அன்பனுமான அந்த ஸ்ரீகிருஷ்ணனுக்கு வணக்கம்.',
        '0.2': 'மூவுலகங்களுக்கு அப்பாலும் ஒளிர்வதும், உள்ளிருக்கும் இருளை மீண்டும் மீண்டும் போக்குவதும், சூரியனின் ஒளியையும் வெல்வதுமான மத்வரின் புகழ் நமக்குத் தெளிந்த பார்வையை அருளட்டும்.',
        '0.3': 'எவருடைய முகச்சந்திரனிலிருந்து எழுந்த தத்துவ தீபங்களைப் போன்ற சொற்களாகிய கதிர்களால் உலகின் இருள் நீங்கி ஆனந்தம் அடைந்ததோ, அந்தச் சிறந்த குருவான த்ரிவிக்ரமாசாரியரை (கவியின் தந்தையை) வணங்குகிறேன்.',
        '0.4': 'குருபக்தியிலிருந்து பிறக்கும் முகுந்த பக்திக்காகவும், நல்லோரின் இடையறாத அருளுக்காகவும், ஜகத்குருவான வாயுதேவரின் அவதாரங்களின் மேன்மையும் தூய்மையும் கொண்ட லீலையைக் கூறுவேன்.',
        '0.5': 'அந்த லீலை வேத மந்திரங்களின் எழுத்துக்களால் வர்ணிக்கத் தக்கது; ருத்திரன், இந்திரன் முதலானோரும் அதைச் சொல்ல விரும்புகின்றனர். மந்த புத்தியுள்ள நான் சுருக்கமாகச் சொல்ல முயலும்போது, குணவான்களான நல்லோர் என்மீது கருணை காட்டட்டும்.',
        '0.6': 'உயர்ந்ததும் தாழ்ந்ததுமான எல்லாச் செயல்களும் எவரால் (அனைவரின் பிராணனான வாயுவால்) நடக்கின்றனவோ, அவருடைய சரிதத்தில் சொல்லத்தக்க வியப்பு என்ன? ஆயினும் புகழ்பெற்றோரின் சிரோமணிகளின் சரிதத்தைச் சொல்வது மனத் தூய்மைக்காகவே.',
        '0.7': 'அவருடைய சரிதமாகிய ரத்தினங்களால் மாலை தொடுக்கும், நுண்ணிய பார்வையில்லாவிடினும் ஆர்வமுள்ள என்னால் முன்பின் வரிசைப் பிழையோ வேறு தவறோ நேர்ந்தால், மகான்கள் மீண்டும் மீண்டும் மன்னிக்கட்டும்.',
        '0.8': 'ஸ்ரீபதியின் ஆணையையும் இந்திரன் முதலிய தேவர்களின் வேண்டுதலையும் மூவுலகிலும் மிகப் பொருத்தமானதாக மதித்து, பிராணங்களின் தலைவரும், உயிர்களை நடத்துபவரும், நல்லோரின் குருவுமான வாயுதேவர் கேசரியின் இல்லத்தில் அவதரித்தார்.',
        '0.9': 'உலகில் புகழ்பெற்ற எந்த எந்த குணங்கள் உண்டோ அவை ஒவ்வொன்றுக்கும் இவரையே எடுத்துக்காட்டாகக் காட்டுகின்றனர்; மகா பாகவதர்களில் நேரடியாக முதன்மையான இந்த ஸ்ரீமானை ஹனுமான் என்று அழைக்கின்றனர்.',
        '0.10': 'தேவசபைகளில் போற்றப்பட்ட மிக அற்புதமான செயல்களைச் செய்தவாறு, அவர் சுக்ரீவனின் நண்பனும் உலகைப் புனிதமாக்குபவனுமான ராமரூபம் கொண்ட ரமாபதியைக் கண்டார்.',
        '0.11': 'அப்போது பெரும் பக்தியின் சுமையால் உந்தப்பட்ட வானரத் தலைவர் திருவடித் தாமரைகளில் வணங்க, அந்தப் புராண புருஷன் தாமரையின் உட்புறம் போல் அழகிய தன் இரு கைகளால் அவரைத் தழுவிக்கொண்டான்.',
        '0.12': 'பிளக்க முடியாத சால மரங்களின் வரிசையைப் பிளந்தவனும், இந்திரனின் மகனான வாலியைக் கொன்றவனும், சூரியனின் மகனான சுக்ரீவனுக்கு மிகுந்த மகிழ்ச்சி அளித்தவனுமான மதுசூதனன் ஸ்ரீராமன் அந்த வீரரை (சீதையைத் தேட) அனுப்பினான்.',
        '0.13': 'காது வரை இழுத்து விடுபவனும், குணங்களை ஏற்பவனும் (வில்லின் நாணைப் பற்றுபவனும்), போரில் வல்லவனுமான ராமனால் விடப்பட்ட அவர், சிறந்த அம்பு போல் ஒளிர்ந்து பகைவருக்கு அச்சமூட்டுபவராகவும் நல்லோர் பக்கம் நிற்பவராகவும் (நல்ல இறகுடையவராகவும்) ஆனார்.',
        '0.14': 'ஆஹா! இந்த ஹனுமான் புதிய மழைமேகம் போன்றவர்: தம் சொற்களால் (மேகம் நீரால்) சீதையை மகிழ்வித்தார், தம் நெருப்பால் ஊனுண்ணும் அரக்கர் கூட்டத்தை (மின்னல் மரங்களை) எரித்தார், கடலைக் கடந்து விஷ்ணுவின் திருவடியில் (வானில்) வணங்கினார்.',
        '0.15': 'மூவுலகிலும் சிறகில்லாதவரும் (பக்ஷபாதமில்லாதவரும்), போகங்களை அனுபவிக்காதவருமான (பாம்புகளை உண்ணாதவருமான) இவர், உலகைத் தாங்கும் ராமனைச் சுமந்து, வேகமான வீரச்செயல்களில் பறவைகளின் அரசனான கருடனையே வென்றார் — இது வியப்பு.',
        '0.16': 'ரகுகுலக் கொடியான ராமன் தன் புருவச் சுளிப்பாலேயே கலங்கிய கடலின் நடுவே அணையைக் கட்டியபின், ஹனுமான் சீதையை அச்சுறுத்தியதற்குத் தக்க பதிலாகப் பத்துத் தலையனான ராவணனுக்கு முஷ்டியால் ஓர் அடி கொடுத்தார்.',
        '0.17': 'சுடர்விட்டு எரியும் ராகவனே அக்னியாகவும் சுக்ரீவனே யஜமானனாகவும் இருந்த போர் என்னும் யாகத்தில், அவர் சுமித்திரையின் மகன் லக்ஷ்மணனைத் துணை ருத்விக்காகக் கொண்டு அத்வர்யுவின் பணியைச் செய்தார்.',
        '0.18': 'ராமனின் பூஜைக்குப் பூவைக் கொண்டுவரும்போது இரு கைகளாலும் கவனமாகக் கொண்டுவந்தார்; சஞ்சீவினி முதலிய மூலிகைகளின் இருப்பிடமான பெருமலையை ஒரே கையால் கொண்டுவரும்போது அவருக்குச் சிறிதும் சிரமம் இல்லை.',
        '0.19': 'பகைவரை அழித்தவனும், அக்னிப் பிரவேசத்தால் தூய்மை வெளிப்பட்ட அரசகுமாரி சீதையுடன் கூடி, பொன் மாலையால் அலங்கரிக்கப்பட்டவன் போல் விளங்கியவனுமான பரம புருஷனுக்கு அவர் சேவை செய்தார்.',
        '0.20': 'கருநிறம், புன்னகை முகம், நீண்டு அகன்ற கைகள், தாமரைக் கண்கள், யானையரசின் நடை கொண்ட, உலகுக்கு மங்களமான அயோத்தி மன்னனின் திருவுருவைக் கண்களால் நெடுங்காலம் அவர் சேவித்தார்.',
        '0.21': 'பட்டாபிஷேகம் முடிந்ததும், “நம்மைப் பணிபவர்களில் மிகவும் அன்பானவனுக்கு இதைக் கொடு” என்ற ராமனின் சொல்லின்படி, சீதை அழகிய ரத்தின மாலையின் சாக்கில் தன் நீண்ட கருணையை அவருக்குக் கட்டினாள்.',
        '0.22': 'இதயத்தின் பெரும் அன்பு நிறைந்த கையை அவர் தலைமேல் வைத்து, கருணையால் நனைந்த பார்வையுடனும் அமுதம் போன்ற சொல்லுடனும், சேவையால் மகிழ்ந்த இறைவன் அவருக்குத் தன்னுடன் சேர்ந்த போகத்தை அருளினான்.',
        '0.23': 'ராமனுக்கு அவரைவிட அன்பானவர் எவரும் இல்லை; ராமராஜ்யத்தில் கிடைக்கக் கடினமானது எதுவும் இல்லை; ஆயினும் அவன் திருவடிச் சேவையிலேயே இன்புற்ற ஹனுமான் போகங்களை விரும்பவில்லை — அதுவே உண்மையான வைராக்கியம்.',
        '0.24': '“நாதா, நமோ நமஹ, உனக்கு நமோ நமஹ; ராமா, நமோ நமஹ, உனக்கு நமோ நமஹ; நாதா, உன் திருவடித் தாமரையை மீண்டும் மீண்டும் வணங்குகிறேன்” என்று வணங்கியவாறு அவர் மகிழ்ந்தார்.',
        '0.25': 'அந்த வானரத் தலைவர்மீது சீதாபதி காட்டிய பேரருளை எப்படி வர்ணிப்போம்! பூமியை விட்டுச் செல்லும்போது நித்திய சேவைக்காகத் தன்னையே அவருக்குக் கொடுத்தான்.',
        '0.26': 'பக்தர்களுக்கு ஆனந்தக் காரணமான ராமகதை அமுதத்தில் எப்போதும் மூழ்கியிருக்கும் அவர், இப்போதும் கிம்புருஷ வர்ஷத்தில் தம் தலைவன் ராமனுக்குச் சேவை செய்துகொண்டு வாழ்கிறார்.',
        '0.27': 'அதே வாயுதேவரின் இரண்டாவது அவதாரமே பீமன் என்று நல்லோர் கூறுகின்றனர்; அன்புகொண்ட வாயுவின் தொடுதல் மாத்திரத்தாலேயே பாண்டு மன்னனின் அரசி குந்தி அவனைப் பெற்றாள்.',
        '0.28': 'முன்பு இந்திரனின் கையால் வீசப்பட்ட வஜ்ராயுதம் மலைகளின் சிறகுகளை மட்டுமே வெட்டியது; ஆனால் தாயின் கையிலிருந்து நழுவி விழுந்த இந்தக் குழந்தை தன் உடல் தொடுதலாலேயே மலையின் உடலைப் பிளந்தது — இது வியப்பு!',
        '0.29': 'நகரில் இளவரசர்களின் சோம்பலான விளையாட்டுகளைக் கண்டு அவற்றில் ஆர்வமில்லாத பீமன், சிங்கக் கூட்டங்களைக் கொன்ற காட்டில் நடந்த தன் சிறுவயது விளையாட்டை ஏக்கத்துடன் நினைவுகூர்ந்தான்.',
        '0.30': 'பகைவன் கொடுத்த விஷத்தை உண்டு செரித்துக்கொண்டான்; அதனால் பாம்புகளின் விஷ வலிமையும் சோர்ந்தது; பிரமாணகோடியிலிருந்து விளையாட்டாகத் திரும்பி வந்தான். உலகுக்கு உயிர் தருபவனிடம் இது வியப்பல்ல.',
        '0.31': 'யோகி யோக பலத்தால் உடலை எரித்துத் தன் தர்மங்களைச் சுமந்து நாராயணனை அடைவது போல், பீமன் அரக்கு மாளிகையை எரித்து, சகோதரர்களைச் சுமந்து வெளியேறி, உலகம் போற்ற வியாசரூபியான நாராயணனை அடைந்தான்.',
        '0.32': 'தூய மனமுடைய அந்தச் செயல்வீரன் இதுவரை செய்த நற்செயல்களை எல்லாம் அனந்தனான வியாசருக்கு அர்ப்பணித்து, இனிச் செய்யப்போகும் செயல்களையும் அவருடைய பூஜையாகவே சங்கல்பித்தான்.',
        '0.33': 'பிறகு வானைச் சார்ந்திருந்த கொக்கை (பகாசுரனை) அகற்றியவனும், பிற பறவைகளை (பகைவரை) விரட்டியவனும், நல்ல சிறகுடையவனுமான (நல்ல துணையுடையவனுமான) அந்த ராஜஹம்சம், சகோதரர்களுடன் ராஜஹம்சியைப் போல் அரசகுமாரி திரௌபதியைப் பெற்றான்.',
        '0.34': 'நீலத் தாமரையின் அழகை வெல்லும் எழிலும், புன்னகைக்கும் சந்திர முகமும், தாமரை போன்ற நீண்ட கண்களும் கொண்ட, தன் மாமன் மகனான அன்பு முகுந்தனுடன் பீமன் நெடுங்காலம் மகிழ்ந்திருந்தான்.',
        '0.35': 'அந்த வீரன், பெரும் கதை ஏந்தியவனும் போரில் கடுமையானவனுமான பிருஹத்ரதனின் மகன் ஜராசந்தனை விரைவில் வீழ்த்தி, கோவிந்தனுடனும் இந்திரனின் மகன் அர்ஜுனனுடனும் சேர்ந்து யுதிஷ்டிர மன்னனைக் கொண்டு மிக ஒளிமிக்க ராஜசூய யாகம் செய்வித்தான்.',
        '0.36': 'பகைவரைக் கொல்லும் விருப்பத்தால் கடுமையான பீமன், துச்சாசனனால் கலைக்கப்பட்ட தன் அன்பு மனைவியின் மெல்லிய, சுருண்ட, கரிய கூந்தலைக் கருநாகங்களைச் சேகரிப்பது போல் சேகரித்தான்.',
        '0.37': 'காட்டுக்குக் காடு கொழுந்துவிட்டு எரிந்து, கொடிய அரசர் கூட்டத்தை எரிக்க விரும்பிய விருகோதரன் என்னும் நெருப்பின் பெரும் வெப்பத்தால், மனிதர்களுக்கு அச்சமூட்டிய உயிரினங்கள் அழிந்தன.',
        '0.38': 'மலையரசின் மேல் அங்குமிங்கும் திரிந்த, பெரிய உடலும் சிவந்த கண்களும் பாம்புகளைப் போல் இரட்டை நாக்கும் கொண்ட, மணிமான் முதலான பல கொடிய குரோதவச அரக்கர்களை அவன் கொன்றான்.',
        '0.39': 'பிறகு சாம்பலில் மறைந்த நெருப்பைப் போல் வேறு வேடத்தில் மறைந்திருந்த ஒளிமிக்க வாயுபுத்திரன், எல்லாத் திசைகளையும் அடைத்திருந்த, ஆரவாரமான, கொடிய கீசகர் கூட்டம் முழுவதையும் படிப்படியாகச் சாம்பலாக்கினான்.',
        '0.40': 'கருமையான பாதையுடைய நெருப்பைப் போல் கிருஷ்ணனின் வழியைப் பின்பற்றி, விஜயனுடன் (அர்ஜுனன்/வெற்றி) கூடி, மீண்டும் மீண்டும் பெரும் ஆயுதங்களை (ஜ்வாலைகளை) ஏந்தி, வெல்லமுடியாதவனாக, பீஷ்மர் துரோணர் முதலானோரால் பயங்கரமான பகைவர் காட்டை எரித்தவாறு அவன் ஒளிர்ந்தான்.',
        '0.41': 'வலிமையுள்ளவர்களும், எழுந்து வந்தவர்களும், பொறுமையற்றவர்களும், மிகக் கடுங்கோபமுள்ளவர்களும், சிறகு (பக்ஷம்) எரிந்தவர்களுமான திருதராஷ்டிரனின் மகன்கள் அனைவரையும் அழித்து, பல ஆயுதங்களுடன் விளையாடும் அவன் பேரொளியுடன் விளங்கினான்.',
        '0.42': 'கிருஷ்ணனின் திருவடித் தாமரைகளுக்கு வண்டரசனும், கிருஷ்ணையின் (திரௌபதியின்) முகத் தாமரைக்கு அன்னவரசனும், மக்களாகிய தாமரை வரிசைக்குச் சூரியனுமான வீரர்களின் அரசன் பீமன் சகோதரர்களுடன் விளங்கினான்.',
        '0.43': 'தன் சகோதரன் அர்ஜுனனின் பேரனான பரீக்ஷித்திடம் பூமியையும், அசுரர்களின் மனத்தில் துன்பத்தையும், மூவுலகில் புகழையும், இதயத்தில் முகுந்தனையும் வைத்து, பீமன் சகோதரர்களுடன் தன் இருப்பிடத்தை அடைந்தான்.',
        '0.44': 'இவ்வாறு விஷ்ணுவின் திருவடிக்குச் சேவை செய்யும் வாயுவின் கொடிய அடிகளால் அழிந்த தேவபகைவர்கள், காற்றால் சிதறிய மேகங்களைப் போல் சாரத்தை இழந்து, நிலையற்ற நடத்தையுடன் ஒளியை இழந்தனர்.',
        '0.45': 'இதற்குப் பழிவாங்க விரும்பிய, வலிமை இழந்த அவர்கள் இவ்வாறு துன்பத்தில் சிக்கி, காலப்போக்கில் கலியுகத்தில் தங்களுக்குத் தகுந்த “முகுந்தன் குணமற்றவன்” என்ற கொள்கையை உருவாக்கினர்.',
        '0.46': '(இங்கிருந்து கவியின் கண்டனப் பகுதி.) முன்பு பீமனால் கொல்லப்பட்ட, பெரும் பகைமை கொண்ட, சொல்வன்மையுள்ள, மேலாதிக்கத்தை விரும்பிய, ஈசனை மகிழ்வித்திருந்த மணிமான் “சங்கரன்” என்ற பெயருடன் பூமியில் பிறந்தான்; பிற அசுரத் தலைவர்களும் போட்டியுடன் இங்கே பிறந்தனர்.',
        '0.47': 'உள்ளத்தில் அறிவில்லாத பூனை யாகத்தின் ஹவிஸைப் பற்றுவது போலவும், சாரமற்றதை விரும்பும் நாய் புரோடாசத்தைப் பற்றுவது போலவும், நிலையற்ற குரங்கு ரத்தின மாலையைப் பற்றுவது போலவும், இந்தப் பாவி வேதம் முதலியவற்றைப் பற்றினான்.',
        '0.48': '“இல்லாவிட்டால் மக்கள் வணங்கமாட்டார்கள்” என்று எண்ணி அந்த வஞ்சகன் நான்காவது ஆசிரமமான சந்நியாசத்தை ஏற்றான் — தெளிந்த தாமரைக் குளத்தைக் கலக்க விரும்பி அடங்காத கொடிய யானை அதில் நுழைவது போல.',
        '0.49': 'வேதத்துக்குப் புறம்பான மாத்யமிக (பௌத்த) மதம் மறுக்கப்பட்டதைக் கண்டு, அந்தப் பக்கத்தின் சார்பாளனான அவன் அதே கொள்கையை நிறுவுவதற்கேற்ற வழியை இங்கே வகுத்தான்.',
        '0.50': 'பௌத்தர்கள் “அசத்” என்ற இடத்தில் அவன் சத், அசத் இரண்டிலிருந்தும் வேறுபட்டதைக் கூறி, அவர்களின் “ஸம்வ்ருதி”க்கு “மாயை” என்று பெயரிட்டான்; சூனியத்தை நிறுவ பிரம்மத்தையும் அகண்டம் என்றான் — ஆகவே அவன் மறைந்த பௌத்தன் என்று புகழ்பெற்றான் எனக் கவி கூறுகிறார்.',
        '0.51': 'வேதத் தொகுதியாகிய குதிரையையும், தன் கதிர்களால் (வாக்கியங்களால்) அனைத்தையும் ஒளிரச் செய்யும் பிரம்மசூத்திரத் தொகுதியாகிய சூரியனையும் அவன் திருடியதால், அவனைப் பெருந்திருடன் என்று அழைக்கின்றனர்.',
        '0.52': 'வியாசர் இயற்றிய சூத்திரங்களுக்கே எதிராகப் பேசி “நானே அவற்றின் பாஷ்யகாரன்” என்று சொன்னவனை அக்கணமே எரிக்க விரும்பாத வியாசரூபியான பகவான் பொறுமைக் கடல்.',
        '0.53': 'வேதங்களாகிய சிறந்த மணிவிளக்குகளின் ஒளி அவனுடைய பரந்த சொற்கூட்டம் என்னும் சேற்றில் மறைந்தது; அறியாதோருக்குக் குழப்பத்தின் (ஸங்கரதையின்) சுரங்கமானதால் அவன் “சங்கரன்” என்று அறியப்பட்டான் என்பர்.',
        '0.54': '“உலகம் பொய், இறைவன் குணமற்றவன், ஆத்மாக்களுக்குள் வேறுபாடில்லை” என்று தைத்தியர்கள் தங்கள் சொல்லை எல்லாத் திசைகளிலும் பெரிதும் பரப்பினர்; ஐயோ! ஆனந்தம் முதலிய மகா குணங்களால் நிறைந்த வாசுதேவன் நல்லோரின் மனத்திலும் மெல்ல மெல்ல மறைந்தான்.',
        '0.55': 'இவ்வாறு கவிகுலத் திலகரான த்ரிவிக்ரம பண்டிதாசாரியரின் மகன் நாராயண பண்டிதாசாரியர் இயற்றிய, “ஆனந்த” என்ற முத்திரை கொண்ட ஸ்ரீமத் ஸுமத்வ விஜய மகாகாவியத்தின் முதல் சர்க்கம் நிறைவுற்றது.',
      },
    },
    'sumadhva-vijaya-02': {
      verses: {
        '0.0': 'காலத்தின் வலிமையால் ஞானச் சூரியன் மறைய, தவறான பாஷ்யங்கள் என்னும் அடர்ந்த இருளால் குருடான மக்கள் நல்லோரின் வழியிலிருந்து நழுவ, மனம் சோர்ந்த நான்முகன் பிரம்மா முதலிய தேவர்கள் முகுந்தனைச் சரணடைந்தனர்.',
        '0.1': 'மூன்று யுகங்களில் மட்டுமே வெளிப்படுவதால் “த்ரியுகன்” எனப்படும் இறைவன், கலியுகத்தில் அவதரிக்க விரும்பாமலும், அவதாரமற்ற பிரம்மனுக்கு ஆணையிட விரும்பாமலும், அப்பணிக்குத் தகுந்த வேறு சர்வஞ்ஞனைக் காணாமலும், புன்னகையுடன் உலகின் உயிரான வாயுவிடம் கூறினான்.',
        '0.2': '“வேதாந்த வழியைத் தேடி வருந்தித் துயருறும் தெய்விக மக்கள் புகலிடமின்றி நம் கருணைக்கு உரியவர்களாக உள்ளனர். அழகிய முகத்தோனே, வேறொரு உருவில் பூமியின் ஒரு பகுதியை அலங்கரித்து, என் நற்குணங்களை நிலைநாட்டி அவர்களை மகிழ்விப்பாயாக.”',
        '0.3': 'கைகூப்பி வாயுதேவர் அந்த ஆணையை ஒளிமிக்க விலைமதிப்பற்ற முடிமணியைப் போல் தலையில் தாங்கி, தேவர்களின் வேண்டுதலை மாலையைப் போல் இதயத்தில் தாங்கி, தம்மவர்களுக்கு அருள விரும்பி அவதரிக்கத் தீர்மானித்தார்.',
        '0.4': '“வேதாந்தத்தின் முடிந்த முடிவின் சாரத்தை நாம் அறியோம்; ஐயோ, நன்மையை எப்படி அடைவோம்?” என்று நல்லோரின் பல குலங்கள் கவலையுற்ற காலமே அப்போது வந்தது.',
        '0.5': 'அவர்களை மகிழ்விக்கவும் நற்செய்தி அறிவிக்கவும், ஒரு பெருவிழாவுக்கு ஆர்வத்துடன் ஆரவாரமாக மக்கள் பெருந்திரள் கூடியிருந்தபோது, ரஜதபீடபுரத்தில் (உடுப்பியில்) வாழும் இறைவன் ஒரு மனிதனுள் ஆவேசித்தான்.',
        '0.6': 'இயல்பாகத் திறமையற்ற அந்த மனிதனுள் ஆவேசித்து, தம் மக்களுக்கு நம்பிக்கையூட்டி, உயர்ந்த கொடிமரத்தின் உச்சியில் மேடையிலுள்ள நடிகனைப் போல் அங்க அசைவுகள் செய்து, அனைவரும் வியக்கும்படி நன்றாக ஆடினான்.',
        '0.7': 'அங்கிருந்த மக்களை நோக்கி, கையை உயர்த்தி, சத்தியம் செய்து உரக்க இவ்வாறு கூறினான்: “அனைவருக்கும் நன்மை செய்யும் சர்வஞ்ஞனான பகவான் விரைவில் இங்கே உலகில் பிறப்பான்.”',
        '0.8': 'ஏழு தீவுகளும் ஏழு கடல்களும் கொண்ட பூமியில், கர்மபூமியான பாரதகண்டத்தில், கலியுகத்தில், மிகத் தூய குலத்தில் பிறந்த, நல்லோரான மத்யகேஹ குலத்தின் முடிமணியான ஓர் அந்தணர் இருந்தார்.',
        '0.9': 'வேதாத்ரி மற்றும் புனித ரஜதபீடபுரத்தின் இறைவர்களால் அலங்கரிக்கப்பட்ட, மேருமலையின் அதிபதியால் ஒளிரும் இலாவ்ருதம் போல் விளங்கும், சிறந்த குணங்கள் கொண்ட சிவரூப்யம் (சிவள்ளி) என்ற கிராமமே அவருடைய பூர்வீக இடம்.',
        '0.10': 'மூன்று குலங்களுக்கும் ஒரே கொடி போன்ற அவர், பரசுராமனால் பிரதிஷ்டை செய்யப்பட்ட ஹரியின் தங்கை துர்க்கையின் ஒளிரும் விமானம் உச்சியில் உள்ள குன்றால் விளங்கும் “பாஜகம்” என்ற க்ஷேத்திரத்தில் வாழ்ந்தார்; உலகைக் காப்பதால் (பாஜ) எப்போதும் இன்பத்தை (க) தாங்குவதால் அது பாஜகம்.',
        '0.11': 'புருஷார்த்தத்துக்குக் காரணமான ஒப்பற்ற செல்வத்தைத் தரத் தகுந்தவளும், பொருத்தமான வடிவுடையவளும், பொன்போல் ஒளிர்பவளுமான (நல்ல எழுத்துக்களால் விளங்கும் வேத வித்யை போன்றவளுமான), சிறந்த அந்தணர் அளித்த கன்னிகையை அவர் மணந்தார்.',
        '0.12': 'பெரும் விவேகி தூய உபநிஷத்திலும், தூய புலன்கள் உடையவன் பக்தியிலும், பொய்யான அகந்தையற்றவன் பரம முக்தியிலும் இன்புறுவது போல், அந்த அந்தணர் தலைவர் இடையறாத ஆனந்தம் தரும் அவளுடன் இன்புற்றார்.',
        '0.13': 'தம் தர்மத்தில் ஈடுபட்ட அந்த உறுதியானவர், குலதெய்வமான அந்த இறைவனின் திருவடிகளில் பக்தியைப் பிணைத்தார்; பாரதம், புராணங்களின் பெரும் ரகசியத்தை அறிந்த அந்த அடக்கமானவரை மக்கள் “பட்டர்” என்று அழைக்கின்றனர்.',
        '0.14': 'கோவிந்தனின் அழகிய கதை அமுதத்தால் அவர் மனிதர்களின் புலன்களை மட்டுமல்ல, ரஜதபீடபுரத்தில் ஸ்ரீபதியின் திருவடித் தாமரைகளைப் பணியும் தேவர்களையும் மகிழ்வித்தார்.',
        '0.15': 'இவ்வாறு ஹரியின் குணக் கதை அமுதத்தால் நிறைவுற்றிருந்தும், நிர்குண வாதத்தில் பிடிவாதமுள்ள மக்களைக் கண்டு, காலத்தின் தாக்கத்தால் தத்துவத்தில் ஐயமுற்ற அந்த அறிஞர், கேட்டலால் தூய்மையான அறிவால் சிந்தித்தார்.',
        '0.16': '“‘புத்’ என்னும் நரகத்திலிருந்து காப்பவனே புத்திரன்; நிறைவற்ற மனிதனிடமிருந்து முதன்மையான காப்பு எளிதல்ல. ஆகவே அனைத்தும் அறிந்தவனும் குற்றமற்றவனும் கல்வியின் சுரங்கம் போன்றவனுமான மகனை எந்த உபாயங்களால் பெறுவோம்?”',
        '0.17': '“முன்பும் கர்தமர், பராசரர், பாண்டு முதலானோர் எவருக்குச் சேவை செய்து குணம் நிறைந்த மக்களைப் பெற்றனரோ, நற்குணங்கள் நிறைந்த திருமேனியனும் கருணை அமுதக் கடலும் குலநாதனுமான அந்த நாராயணனைச் சரணடைவோம்.”',
        '0.18': 'இவ்வாறு சிந்தித்து, வேறு உறவற்ற அந்த நல்லுள்ளத்தவர், தியானிக்கத் தகுந்தவனும், அன்பானதை அருள்பவனும், சம்சாரக் கடலின் அச்சத்தை அழிப்பவனும், ரஜதபீடபுரத்தில் வாழ்பவனும், அரவணையில் துயில்பவனுமான பகவானைப் பன்னிரண்டு ஆண்டுகள் பக்தியுடன் வழிபட்டார்.',
        '0.19': 'மனைவியுடன் இறைவனின் திருவடித் தாமரையை வழிபட்டவாறு, அவர் சிறிய போகங்களையும் இன்னும் குறைத்தார்; இயல்பாக அடங்கிய மனத்தை மேலும் அடக்கினார்; தூய உடலை இன்னும் தூய்மையாக்கினார்.',
        '0.20': 'குணக் கடலான மகனை விரும்பிய அந்தத் தம்பதியர், பால் மட்டுமே உண்ணும் விரதம் முதலிய கடுமையான பல சிறந்த விரதங்களால், முன்பு தேவர்களால் தூண்டப்பட்ட அதிதி, காசியபர் போல், பூரண புருஷனை மிகவும் மகிழ்வித்தனர்.',
        '0.21': 'இறைவனின் பெரும் கருணை அமுதத்தால் நீராட்டப்பட்டவர்களும், ஸ்ரீ, ஸ்ரீதரனின் அருளின் சாரத்தால் வளம் பெற்ற மெலிந்த உடல்களை உடையவர்களும், பல விரதங்களால் உண்டான தெய்விக ஒளி கொண்டவர்களுமான அவர்கள், உடல் தூய்மையையும் மனத் தூய்மையையும் அடைந்தனர்.',
        '0.22': 'பிறகு உரிய காலத்தில் கணவனால் மதிக்கப்பட்ட அந்த அந்தணர் மகள் உலகங்களின் இன்பத்திற்காகக் கருவுற்றாள் — தெளிந்த வானமுடைய, திசைகளை நம்பிக்கையால் நிறைக்கும் இரவு இருளைப் போக்கும் வளர்பிறைச் சந்திரனைத் தாங்குவது போல.',
        '0.23': 'வளர்பிறைச் சந்திர பிம்பம் போல் வளர்ந்த அவனை அந்த அந்தணர் மனைவி பெறுவதற்கு முன்பே, வாயுதேவர் தம் அம்சத்துடன் இறங்கி, ரூப்யபீடத்தில் (உடுப்பியில்) விஷ்ணுவை வணங்கி அவர்கள் இல்லத்திற்குச் சென்றார்.',
        '0.24': 'அரசன் சிறந்த நகரில் நுழைவது போல், எல்லா நல்லிலக்கணங்களும் கொண்ட, ஒளிரும் ஒன்பது வாயில்களுடைய அந்த மிக அழகிய மாளிகையில் (உடலில்), உலகங்களின் அதிபதியான அந்தப் பகவான் பிறரை வெளியேற்றியவாறு நுழைந்தான்.',
        '0.25': '“நல்லோர் அனைவரும் மகிழட்டும், தீயோர் வருந்தட்டும்; இந்த வாயு பூமியில் தோன்றினார்” என்று அறிவிப்பது போல், தேவ துந்துபிகளின் ஆழ்ந்த ஒலி வியப்புற்ற மனிதர்களுக்கும் இங்கே கேட்டது.',
        '0.26': 'இறைவனை வழிபட்டு வீட்டருகே வந்த அந்த அறிஞர், விழாவுக்குப் போல் முழங்கிய துந்துபி ஒலியையும் பின் மகன் பிறந்த செய்தியையும் கேட்டுப் பேரின்பம் அடைந்தார்; தம் விருப்பம் நிறைவேறியது என்ற மறைமுக அறிவையும் பெற்றார்.',
        '0.27': 'இல்லத்தில் நுழைந்து, சந்திர முகமுடைய தன் மகனை மீண்டும் மீண்டும் மகிழ்ந்து வாழ்த்தி, முகுந்தனின் கருணையை வணங்கி, நற்செயலாளரான அவர் குணக்கூட்டத்தைத் தாங்கிப் பிறந்த அந்தக் குழந்தைக்கு ஜாதகர்மம் முதலிய சடங்குகளைச் செய்தார்.',
        '0.28': 'ஞானத்திற்காகவே இந்த அசுதேவர் (பிராணதேவர்) அவதரித்ததாலும், எப்போதும் வாசுதேவனின் திருவடி பக்தியில் ஈடுபட்டிருந்ததாலும், பெயரிட்ட தந்தை வைத்த “வாசுதேவன்” என்ற பெயரையே தேவர்களும் ஏற்றுக் கூறினர்.',
        '0.29': 'குழந்தை பால் அருந்தப் பசுவைத் தானம் செய்த பூர்வாலய குடும்பத்தைச் சேர்ந்த ஒருவர், பின்னர் தம் மகனின் மகனாகவே பிறந்து, முக்திக்குக் காரணமான பரமாத்ம வித்யையைப் பெற்றார்; தானம் பெறுபவரின் தகுதிக்கேற்ப நிச்சயம் பலன் தரும்.',
        '0.30': 'ஒருமுறை ஓர் அறிஞரான உறவினர், ஒருபோதும் அஞ்சாத, எப்போதும் மலர்ந்த கண்களுடைய, ஒளியால் புதுச் சந்திரனையும் பழிக்கும், உலகில் விலைமதிப்பற்ற அந்த மகன் ரத்தினத்தை எடுத்துத் தம் இறைவனுக்கு (உடுப்பி இறைவனுக்கு) காணிக்கையாக அர்ப்பணித்தார்.',
        '0.31': 'ரஜதபீடபுரத்தில் வாழும் ஹரியை வணங்கி, குழந்தைக்கு ஆபத்தில்லாத செல்வத்தை வேண்டி, அவர் குழந்தையுடனும் உடன் வந்தோருடனும் நள்ளிரவில் தம் இல்லம் நோக்கிப் புறப்பட்டார்.',
        '0.32': 'மிகப் பயங்கரமான காட்டில் இரவில் அவருடன் சென்றவர்களில் ஒருவனை அங்கே திரியும் ஒரு கிரகம் (பூதம்) தாக்கியது; அவன் இரத்தம் கக்குவதைக் கண்டு யாரோ “ஆஹா! குழந்தைகளைத் துன்புறுத்தும் இது குழந்தையை விட்டு ஏன் இப்படிச் செய்தது?” என்றார்.',
        '0.33': 'அந்தப் பெரும் கிரகம் ஒரு மனிதனுள் ஆவேசித்துக் கூறியது: “எங்கள் உலாவும் நேரத்தில் வருபவர்கள் அனைவரையும், அவருடைய சக்தியின் காப்பு இல்லையெனில், கொல்ல என்னால் முடியும்; ஆனால் உலகநாதனான அவர் பார்வைக்கு மட்டுமே சிறு குழந்தை!”',
        '0.34': 'ஒருமுறை பாலூட்டிக் குழந்தையை நிறைவுறச் செய்து, பிரிவைத் தாங்க முடியாவிடினும் தாய் வீட்டை விட்டு வெளியே சென்றாள்; அச்சமுள்ள அவள் உலகைக் காப்பவனைக் காக்கத் தன் மகளை விட்டுச் சென்றாள்!',
        '0.35': 'அழுத குழந்தையைச் சமாதானப்படுத்தியவாறு அந்தக் கள்ளமற்ற சிறுமி மழலைச் சொற்களால் கொஞ்சினாள்: “அழாதே கண்ணே, அழகு முகமே; அம்மா உனக்குப் பிடித்ததை விரைவில் கொண்டுவருவாள்.”',
        '0.36': 'குழந்தையின் அழுகை மீண்டும் மீண்டும் தொடர, நெடுநேரமாகியும் தாய் வராததால், அந்தச் சிறுமி குழந்தையைத் தூக்கிக்கொண்டு தானும் மீண்டும் மீண்டும் தாயின் வழியைப் பார்த்துக்கொண்டிருந்தாள்.',
        '0.37': 'என்ன செய்வதென்று தெரியாமல், முடிவுசெய்து, நன்கு வெந்த கொள்ளுக் குவியலையே அவனுக்கு ஊட்டினாள்; குளிர்ந்த நீரையும் குடிக்கக் கொடுத்தாள் — கொள்ளின் சூட்டு நோயைக் கண்டு தாய் மிகவும் அஞ்சுவாள்.',
        '0.38': '“ஐயோ, குழந்தை தாகத்தால் மிகவும் அழுதுகொண்டிருக்கும்; பிறர் வேலையில் ஈடுபட்ட இரக்கமற்ற எனக்கு அவமானம்!” என்று பதற்றத்துடன் வீடு வந்த அந்தணர் மனைவி, மகிழ்ச்சியாக வயிறு நிறைந்திருந்த மகனைக் கண்டாள்.',
        '0.39': 'கேட்டு நடந்தவற்றையெல்லாம் அறிந்து, “இளைஞருக்கும் செரிக்கக் கடினமானதைக் குழந்தை உண்டுவிட்டது” என்று எண்ணி, மகளைக் கடுமையாகக் கடிந்தாள் — முதலில் அஞ்சி, பின் கோபித்து, பின் மனதில் வருந்தினாள்.',
        '0.40': 'மகன் முன்போலவே நலமாக இருக்க, அவன் தாய் வியந்தாள் — எல்லாம் வல்ல அவன் (ஹாலாஹல) விஷத்தைக் குடித்தபோதும் அவனுடைய உண்மைத் தாயான மூவுலகத் தாய் லக்ஷ்மி வியப்படையவில்லை.',
        '0.41': 'தாய் மீண்டும் மீண்டும் தூக்கிப் பாலூட்டினாள்; தந்தை அவனை ஏந்தி நலனுக்காக ஜபித்தார்; மற்றவர்களும் கொஞ்சினர்; ஆனால் அனைவரும் அவனுடைய புன்னகை முகம் என்னும் அமுதத்திற்காக ஏங்கினர்.',
        '0.42': 'முதலில் தெளிவற்றிருந்த அவன் வாய்ச் சொல் நாணத்துடன் போல் விளையாடியது — உலகம் போற்றும், தேவர்களாலும் நல்லோராலும் அன்புடன் பேணப்பட்ட, சொற்களால் (அடிகளால்) பாரதீதேவியைப் போலவே விளங்கும் வாக்கு.',
        '0.43': 'அவன் தவழ்ந்தான், பின் தானே நின்றான், பிறகு பழக்கத்தால் படிப்படியாக நடந்தான்; ஆஹா! உலகின் எல்லா அசைவும் எவருடைய அருளால் நடக்கிறதோ, அந்த வாயுவுக்கு இவையெல்லாம் வெறும் நடிப்பே.',
        '0.44': 'ஒருமுறை காலையில் மாட்டுத் தொழுவத்திலிருந்து புறப்பட்ட தன் அன்பான காளையின் வாலின் நுனியைப் பற்றிக்கொண்டு, வீட்டாருக்குத் தெரியாமல், பல காடுகளில் புல் மேய்ந்த அதனுடன் அவன் திடீரெனச் சென்றுவிட்டான்.',
        '0.45': 'உயர்ந்து ஒளிரும் கொம்புகளும், பெரிய உடலும், குளம்புகளால் நிலத்தை மூடியதுமான அந்தக் காளையின் உடலின் ஒரு பகுதியைப் பற்றியிருந்த அந்தக் குழந்தை, உதயமலை மேல் இளஞ்சூரியனைப் போல் ஒளிர்ந்தது.',
        '0.46': '“குழந்தை விளையாடுகிறதா? வேறு வீட்டுக்குப் போயிற்றா? இயல்பிலேயே சுதந்திரமான அவன் கிணற்றில் விழுந்தானா?” என்று எண்ணி வீட்டார் மீண்டும் மீண்டும் தேடி, ஐயோ, மகனைக் காணாமல் மனம் வெதும்பினர்.',
        '0.47': 'குழந்தை காளையைப் பற்றியிருந்தது பற்றிக் காட்டுவாசிகள் சொன்னது நம்பத்தக்கதாயிற்று; ஏனெனில் மாலையில் ஒரு வயதுக் குழந்தை இளம் காளையைப் பற்றிக்கொண்டு திரும்பி வருவதை மக்கள் கண்டனர்.',
        '0.48': 'ஏழை விரும்பியதைத் தரும் சிந்தாமணியைப் பெற்றது போலவும், முக்தியை நாடுபவன் விஷ்ணுவை மையமாகக் கொண்ட ஞான வழியைப் பெற்றது போலவும், தொலைந்த மகனைத் திரும்பப் பெற்ற வீட்டார் அதை அந்த இறைவனின் அருளாகவே கருதினர்.',
        '0.49': 'ஒருமுறை விளையாட்டு முடிந்தபின் மகன் உணவுக்கு வரும்படி வற்புறுத்தியபோது, தந்தை மகனின் முகச்சந்திரனைப் பார்த்து மெதுவாக “காளையை விற்ற இந்தக் கடன்காரன் நம்மைத் தடுத்து வைத்திருக்கிறான்” என்றார்.',
        '0.50': 'அப்போது குழந்தை புன்னகைத்துத் தன் மென்மையான விளையாட்டுக் கையால், அவன் விரும்பிய நாணயங்களுக்குப் பதிலாகச் சில விதைகளை உடனே கொடுத்தது; கடன்காரன் அவற்றைப் பெரும் மதிப்புடன் ஏற்றான்.',
        '0.51': '“உங்கள் மகனிடமிருந்து பெற்றுவிட்டேன்” என்று சொல்லி, பின்னர் அந்த அந்தணர் தம் செல்வத்தைத் திருப்பித் தர விரும்பியபோதும் அவன் ஏற்கவில்லை; விதைகள் என்ற சாக்கில், புதிய குழந்தை வடிவிலிருந்த மனிதருக்கு அப்பாற்பட்டவரிடமிருந்து அவன் சிறப்பான புருஷார்த்தத்தையே பெற்றான் — வியப்பு!',
        '0.52': 'பல லீலைகள் செய்யும், பிராண தேவதையின் உண்மையான அம்சமான, “வாசுதேவன்” என்ற புனிதப் பெயர் கொண்ட அந்தக் குழந்தையை மக்கள் நேரே வாசுதேவன் என்பது போல் மகிழ்ந்து போற்றினர்.',
        '0.53': 'இவ்வாறு விஷ்ணுதாசன் மறைந்திருந்தும் பூமியில் உலவ, நல்லோரின் மனம் ஆனந்தத்தால் நிறைந்தது; மேகக் கூட்டத்தில் மறைந்திருந்தாலும் சூரியன் உதிக்கும்போது மக்களின் கண் தாமரைகள் மலர்கின்றன அல்லவா!',
        '0.54': 'இவ்வாறு கவிகுலத் திலகரான த்ரிவிக்ரம பண்டிதாசாரியரின் மகன் நாராயண பண்டிதாசாரியர் இயற்றிய, “ஆனந்த” என்ற முத்திரை கொண்ட ஸ்ரீமத் ஸுமத்வ விஜய மகாகாவியத்தின் இரண்டாம் சர்க்கம் நிறைவுற்றது.',
      },
    },
    'sumadhva-vijaya-03': {
      verses: {
        '0.0': 'ஒருமுறை, அழகிய மகனின் புன்னகை முகச்சந்திரனைப் பார்த்திருந்த மக்களுக்கு அன்பான அந்தத் தம்பதியர், தம் உறவினர் மகிழ்ச்சிக்காகச் சுற்றத்தாருடன் மகிழ்வுடன் ஒரு விழாவுக்குச் சென்றனர்.',
        '0.1': 'உறவினர் வருவதும் போவதும், சந்திப்பும், ஒருவரையொருவர் உபசரிப்பதுமான பரபரப்பில், தாய் அறியாமல் அந்தச் சிறுவன் அந்த ஆரவாரமான வீட்டிலிருந்து சில வழிப்போக்கர்களுடன் வெளியேறினான்.',
        '0.2': '“குழந்தாய், எங்கே போக விரும்புகிறாய்? இப்போது உன்னவர்களை விட்டுச் செல்வது சரியல்ல” என்று வழிப்போக்கர் கூற, நடந்தவாறே அந்தப் பிரபு அமைதியான புன்னகையுடன் பதில் அளித்தான்.',
        '0.3': 'விரைந்து சென்று அங்கே வனதேவதையின் கோயிலில் ரமாபதியை வணங்கினான்; அங்கிருந்து மேலே சென்று “சிறு தென்னை” என்ற பெயருடைய இடத்தின் கோயிலில் உள்ள அவனையும் வணங்கினான்.',
        '0.4': 'பத்மநாபனைக் கண்ட மகிழ்ச்சியால் விரிந்து ஒளிரும் கண்களுடைய, மக்களின் மனம், கண் தாமரைகளுக்குச் சூரியனான அவன் ரஜதபீடபுரத்திற்கு (உடுப்பிக்கு) சென்றான்.',
        '0.5': '“நன்கு செய்யப்பட்ட இந்த ஹரி வணக்கங்கள் பல அசுவமேதங்களை விஞ்சுகின்றன” என்பது போல், தேவர்களும் அந்தணர் கூட்டங்களும் வியப்புடன் பார்த்திருக்க அவன் வணங்கினான்.',
        '0.6': 'அவன் ஹரியை வணங்காத, காணாத, போற்றாத கணமே இல்லை; ஆயினும் இங்கே சிறப்பாக அவ்வாறு செய்து அவன் நல்லோருக்குக் கற்பித்தான்.',
        '0.7': 'மகனைக் காணாமல் மகன்மீது பாசமுள்ள அந்த அந்தணர் தலைவர் தேடலானார்; வழிதோறும் அவன் அடிச்சுவட்டைப் பின்பற்றி விரைந்து சென்று, அவன் சென்ற வழியை மக்களிடம் மீண்டும் மீண்டும் கேட்டார்.',
        '0.8': 'மக்கள் (எப்போதும் வீசும் காற்றும்) காட்டிய வழியில் அடிதோறும் தீவிர ஏக்கத்துடன் சென்ற அந்த அந்தணர் என்னும் பெரும் வண்டு, மகனின் அழகிய புன்னகை முகத் தாமரையைக் கண்டடைந்தது.',
        '0.9': 'பிரிவுத் துயரால் கண்களில் பொங்கிய கண்ணீரை அவர் முன்பே அடக்கியிருந்தார்; இப்போது மகிழ்ச்சியால் பொங்கிய கண்ணீரையும் அடக்கிக்கொண்டு அந்தத் தந்தை இவ்வாறு கூறினார்.',
        '0.10': '“மகனே, உண்மையைச் சொல்; நீ இப்போது இங்கே வந்துவிட்டாய்; ஆனால் சுற்றத்தார் இல்லாத உனக்கு இந்த மிக நீண்ட வழியில் துணை யார், குழந்தாய்?”',
        '0.11': 'தந்தையின் சொல்லைக் கேட்டுத் தாமரைக் கண்ணன் இனிமையாகப் பதில் சொன்னான்: “என் இடத்துக்கு வரும்போதும் அங்கிருந்து மேலே போகும்போதும் வனத்து இறைவனே என் நண்பன்.”',
        '0.12': '“அந்த மற்றொரு கோயிலில் வணங்கி வந்தபோது அங்குள்ள ஹரியே நண்பன். இங்கேயும் கிழக்குத் திசைக் கோயிலின் இறைவனையும், பின் அதீஸ்வரனையும் வணங்கினேன்.”',
        '0.13': '“பின் அவனுடன் வந்து இங்கிருக்கும் பகவானை வணங்கினேன்.” என்று சொல்லி, அந்தக் குழந்தை வியந்த சபையோரால் போற்றப்பட்டு விளங்கியது.',
        '0.14': '“கருணையின் இருப்பிடமே, சுற்றத்தாரின்றிப் பல பூதங்களால் அச்சமூட்டும் வழியில் வந்த, உன் திருவடிகளை நேசிக்கும், குறைந்த புண்ணியமுள்ள என் இந்தக் குழந்தையைக் காப்பாயாக” என்று அந்தணர் வணங்கினார்.',
        '0.15': 'மகனைத் தழுவிக்கொண்டு தவச்செல்வரான அவர் மனைவியுடன் வீடு சென்றார்; அந்த இளஞ்சூரியன் உதிக்க, நல்லோரின் முகத் தாமரைகள் புன்னகைத்தன.',
        '0.16': 'சிறந்த விமானமுள்ள குன்றில் சண்டிகையே (துர்க்கையே) தாயாக அந்தக் குழந்தையைக் கொஞ்சினாள்; இல்லையெனில் துணையில்லாத அவன் மனநிறைவுடன் அங்கே அவ்வளவு நேரம் எப்படித் தங்கியிருப்பான்?',
        '0.17': 'எல்லா ஒலிகளுமான சரஸ்வதியே எவரைத் தானாகவே எப்போதும் வணங்குகிறாளோ, அந்த மகனுக்கு ஒருமுறை அந்த அந்தணர் எழுத்துக்களைக் கற்பிக்கத் தொடங்கினார்.',
        '0.18': '“அப்பா, இந்த எழுத்து வரிசையை நேற்றே எழுதிவிட்டோமே, மீண்டும் ஏன் எழுத வேண்டும்?” என்ற, தன் மேதையைக் காட்டும் அந்த ஹரிபக்தனின் சொல் தந்தையை மகிழ்வித்தது.',
        '0.19': '“இந்தக் குழந்தை மேதையின் கடல்; மக்களின் கண்ணும் சொல்லும் படும் திருஷ்டி இவனைத் தாக்கக்கூடாது” என்று எண்ணி அவர் தம் மகனுக்குத் தனிமையான இடத்தில் கற்பித்தார்.',
        '0.20': 'ஒருமுறை விழாவுக்குச் சென்ற சுற்றத்தாரின் வேண்டுதலால், தாயுடன், அழகிய வாசிப்பால் விளங்கும் சொல்வளமுடைய அந்தப் பிரபு க்ருதவல்லிக்கு (நெய்யம்பள்ளிக்கு) சென்றான்.',
        '0.21': 'அங்கே பெரும் சபையால் சூழப்பட்டுப் புராணக் கதை சொல்லிக்கொண்டிருந்த தௌதபடனின் மகனான சிவன் என்பவனைக் குழந்தை வடிவில் இருந்த பேரறிவாளன் கண்டான்.',
        '0.22': 'ஆராய்வதில் வல்ல அவன் மக்களிடையே மெதுவாகப் புன்னகைத்து இந்தத் தூய சொல்லைக் கூறினான்: “கதை சொல்பவரே, நீங்கள் மகான்களின் கருத்துக்கு மாறாகக் கூறினீர்கள்.”',
        '0.23': 'வாசுதேவன் எனப் பெயருடைய அவன் பேசியபின் மக்கள் சிவனைப் பொருட்படுத்தவில்லை; சிங்கக் குட்டி கர்ஜிக்கும்போது ஊளையிடும் நரியை யார் விரும்புவார்?',
        '0.24': '“அப்படியானால் நீயே கதை சொல்” என்று மக்கள் கூற, அவன் பொருத்தமான பொருளைக் கூறினான்; வியந்த மக்களும் வெற்றியின் முளையைப் போற்றும் தேவர்களும் அவனைக் கொஞ்சினர்.',
        '0.25': 'தாயுடன் வீட்டுக்கு வந்து அவன் தந்தையிடம் அந்தச் செய்தியைச் சொல்லி, “அப்பா சொல்லுங்கள், கதை சொன்ன சிவனின் சொல் தவறா, என்னுடையதா?” என்று கேட்டான்.',
        '0.26': '“மகனே, நீ சொன்னது சரியே” என்று கூறி அவர் வியப்புடன் நினைத்தார்: “என் குழந்தையின் இந்தத் திறமை இயல்பானது; என் இறைவனின் கருணையின் உதயத்தால் பிறந்தது.”',
        '0.27': 'ஒருமுறை கதை சொல்வோரில் முதன்மையான அவன் தந்தை மக்கள் திரளின் நடுவே கதை சொல்லிக்கொண்டிருந்தபோது, அனைவரின் கண்ணுக்கும் மனத்துக்கும் விழாவான அந்தக் கூர்மதியாளன் அவரை விளக்கும்படி செய்தான்.',
        '0.28': 'பல மரங்களை வர்ணிக்கும்போது “லிகுசம்” என்பதன் பொருளைச் சொல்லாமல் கடந்து செல்ல, “அப்பா, அதன் பொருளைச் சொல்லாமல் ஏன் தொடர்கிறீர்கள்?” என்று அவன் மெதுவாகக் கேட்டான்.',
        '0.29': 'தந்தை பதில் சொல்லாததாலும், அங்கிருந்த மக்களும் அறிய விரும்பியதாலும், வேண்டப்பட்ட அவன் அதன் பொருளைக் கூறிச் சபையிடமிருந்து ஒப்பற்ற மரியாதையைப் பெற்றான்.',
        '0.30': 'இவ்வாறு பல அழகிய செயல்களால் உலகம் முழுவதற்கும் வியப்பூட்டி, உரிய வயதை அடைந்த அவனுக்கு உபநயனம் செய்ய அந்த அந்தணர் தலைவர் மனம் கொண்டார்.',
        '0.31': 'உரிய கிரக யோகங்கள் கொண்ட குற்றமற்ற முகூர்த்தத்தை நிர்ணயித்து, அன்பான உறவினருடன் அவர் அந்தணர் குலங்கள் நிறைந்த விழாவை நடத்தினார்.',
        '0.32': 'பல வேதங்களின் வடிவில் அவன் முகமெனும் மேடையில் நெடுங்காலம் ஆட விரும்பிய தேவமங்கையர், தம் கணவருடன் வானிலிருந்து அந்த விழாவை மகிழ்ந்து போற்றினர்.',
        '0.33': 'ஒளிமிக்க அறிவுடைய அவர் உரிய பொருள்களாலும் சடங்குகளாலும் அக்னியை வளர்த்து, அலங்கரிக்கப்பட்ட, நலமுடைய, முடி மழிக்கப்பட்ட மகனுக்கு உபநயனம் செய்தார்.',
        '0.34': '“அக்னிக்கும் குருவுக்கும் சேவை செய், விரதங்களைக் கடைப்பிடி, நல்லொழுக்கத்துடன் இரு, நல்ல சாஸ்திரங்களை நன்கு கற்றுக்கொள்” என்று மூவுலகக் குருவுக்குத் தந்தை போதிக்க, சாட்சிகளாக இருந்த தேவர்கள் வெளிப்படையாகச் சிரித்தனர்.',
        '0.35': 'குமரனின் (ஸ்கந்தனின்) குணங்களையும் வென்ற, மென்மையான, இயல்பாகவே தகுந்த ஒழுக்கத்தில் திறமையான தன் மகனைக் கண்டு அந்த அந்தணர் இடைவிடாமல் கற்பித்து மகிழ்ந்தார்.',
        '0.36': 'ஏழையைப் போல் துண்டுத் துணியை அணிந்து, தம் மேன்மைக்குத் தகாத கால்நடை முதலியவற்றைச் செய்தவாறு — ஆஹா! உலகநாதனின் இந்தத் தன்னை மறைத்தல் தேவசபைகளில் வியப்பை உண்டாக்கியது.',
        '0.37': 'இடையறாத விஷ வெப்பத்தால் எல்லா மக்களையும் கலங்கச் செய்து திரிந்த பாம்பு வடிவ அசுரன் ஒருவன், ஒருமுறை அவனைக் கொல்ல விரும்பி அமைதியின்றி அருகே வந்தான்.',
        '0.38': 'விரைவாகப் படத்தை உயர்த்தி விரித்து அவன் கடித்தும் அந்தச் சிறுவனுக்குக் காயமில்லை; பிரபுவின் சிவந்த அழகிய கால் விரல்களின் விளையாட்டால் நசுங்கிய உடலுடைய அந்தப் பாம்பு துடித்து விழுந்தது.',
        '0.39': 'கருடனின் அலகில் சிக்கியது போல் அந்த அந்தணச் சிறுவனின் காலடியில் சிக்கி அவன் இறந்தான்; மகான்களுக்குத் தகுந்த இந்தச் செயலைத் தேவர்கள் மனதாரப் போற்றினர்.',
        '0.40': 'ருத்திரன், பிருஹஸ்பதி, இந்திரன் முதலிய தேவர் தலைவர்கள் எவருடைய திருவடித் தூசியைத் தாங்குகின்றனரோ, அந்த மனித வேடம் பூண்டவன் அந்தணக் குருவின் பாதங்களை வணங்கிக் கல்வியைத் தொடங்கினான்.',
        '0.41': 'எல்லாக் கலைகளுடன் எல்லா வித்யையும் அவன் உள்ளங்கையில் பந்தைப் போல் எப்போதும் இருந்தது; குருவின் முன் சாதாரண மாணவர்களைப் போல் நடித்த அவன் மனத்தில் அது சக்ரதாரியான விஷ்ணுவுடன் ஒளிர்ந்தது.',
        '0.42': 'கல்வியின் இடைவேளையில், குருவுக்குத் தொலைவில், தன்னைவிட இளையவர்களும் மூத்தவர்களுமான பல திறமையான பிரம்மசாரி நண்பர்களுடன் அவன் மகிழ்ச்சியாக விளையாடினான்.',
        '0.43': 'ஓட்டத்தின் இலக்கைச் சொன்னதும் வேகமான நண்பர்களில் அவனே முன்னால் இருப்பான்; அவன் சிரமமின்றி அப்படிச் செய்தது வியப்பல்ல — மனோவேகத்தையும் வெல்லும் வாயுவே அவன்.',
        '0.44': 'தாவும் வலிமையில் அவன் அப்போது எல்லா மக்களையும் வென்றது மட்டுமல்ல; ஹனுமானின் உடலில் இறைவனின் ஆணையை நிறைவேற்றியபோது வாலியின் மகன் அங்கதன் முதலானோரையும் வென்றிருந்தான்.',
        '0.45': 'நீர் விளையாட்டில் தோற்ற நண்பர்கள் போட்டியுடன் தெளித்த நீரால் நனைந்த, கண் சிமிட்டும் அவன் முகம் புன்னகையின் ஒரு தனி அழகைக் கொண்டிருந்தது.',
        '0.46': 'விளையாட்டு மல்யுத்தத்தில் ஒன்றாக வந்த வலிமையான நண்பர்களை அவன் மெதுவாக வீழ்த்துவான்; ஒன்றாக உண்மையாகவே போருக்கு இறங்கியவர்களை அந்த அந்தணச் சிறுவன் சிரித்தவாறு சிரமமின்றி வீழ்த்தினான்.',
        '0.47': 'பிடிப்பது, அடக்குவது, இறுகப் பற்றுவது, பெரும் பாரம் தூக்குவது முதலியவற்றில் திறமையான அவனை மக்கள் உவமையாக “பீமன்” என்று அழைத்தனர்; அது உண்மையில் சத்தியமே.',
        '0.48': '“அவன் விளையாடுகிறான், தெளிவாக ஓதுவதில்லை, வீட்டுக்குத் தாமதமாக வருகிறான்” என்று பூகவன குலத்து அந்த அந்தணக் குரு அந்த ஜகத்குருவின்மீது திருப்தியடையவில்லை.',
        '0.49': 'ஒருமுறை பாடத்தின் நடுவே வேறிடத்தில் மனம் வைத்தவன் போல் இருந்த அவனிடம் கோபமுற்ற குரு கூறினார்: “வஞ்சகனே, நீ படிப்பதில்லை; நண்பர்களுடன் சேர்ந்து உன் மனம் எப்போதும் ஏன் அக்கறையின்றி இருக்கிறது?”',
        '0.50': '“பாதம் பாதமாக மீண்டும் மீண்டும் சொல்ல வைக்கும் பாடம் என் மனதுக்குப் பிடிக்கவில்லை” என்று அவன் சொல்ல, “சாமர்த்தியமாகப் பேசுபவனே, அடுத்ததை உன் விருப்பப்படி சொல்” என்றார் அந்த அந்தணர்.',
        '0.51': 'எல்லா இலக்கணப் பயிற்சிக்கும் மூலமான, பிழையற்ற அவனுடைய வேத ஓதல் அந்தக் குருவுக்கு மட்டுமல்ல, தேவர்களுக்கும் வியப்பை உண்டாக்கியது.',
        '0.52': 'ஒருமுறை ஆளில்லாத காட்டில் அவன் தன் அன்பு நண்பனின் பிறவியிலிருந்தே இருந்த தாங்க முடியாத கடும் தலைவலியைக் காதில் ஊதிய வாய்க்காற்றால் தணித்தான்.',
        '0.53': 'ஒருமுறை கேட்ட உபநிஷத் அவனுக்குக் கைவந்ததும், பாகவதம் தெளிவானதும் வியப்பல்ல; ஒருபோதும் கேளாத நூற்றுக்கணக்கான சுருதிகளையும் அவன் மேதையால் அறிந்திருந்தான்.',
        '0.54': 'பிறகு அந்தப் பிரபு தனிமையில் ஐதரேய உபநிஷத்தை ஓதும் சாக்கில் அதன் பொருள் சாரத்தை விளக்கி, முக்தியின் விதையான கோவிந்த பக்தியைத் தகுந்த குருதட்சிணையாக ஆசிரியருக்கு அளித்தான்.',
        '0.55': '“சுவாமி, தீயோரை விரைவில் வெளிப்படையாக அடக்கு, அடக்கு; உன்னவர்களை மகிழ்வித்து விஷ்ணுவின் மறைந்த குணங்களைச் சொல், சொல்” என்று வேண்டிய தேவர்களுக்கு ஆனந்தம் அளித்தவாறு, மூவுலகக் குரு தம் அந்தணக் குருவிடம் விடை பெற்றார்.',
        '0.56': 'இவ்வாறு கவிகுலத் திலகரான த்ரிவிக்ரம பண்டிதாசாரியரின் மகன் நாராயண பண்டிதாசாரியர் இயற்றிய, “ஆனந்த” என்ற முத்திரை கொண்ட ஸ்ரீமத் ஸுமத்வ விஜய மகாகாவியத்தின் மூன்றாம் சர்க்கம் நிறைவுற்றது.',
      },
    },
    'sumadhva-vijaya-04': {
      verses: {
        '0.0': 'பிறகு நல்ல சாஸ்திரங்களின் ஊற்றான அந்த அறிஞர், நல்லோர்மீதான கருணை அமுதத்தால் நனைந்த, பொய்யை மறுக்க விரும்பும், ரமாபதி வாழும் இடமான தம் பரந்த அறிவால் இவ்வாறு சிந்தித்தார்.',
        '0.1': '“மற்றவற்றில் பற்றின்மையாலேயே ஹரியின் குணங்களில் பற்று உண்டாகிறது; மக்களுக்கு மேலோரின் நடத்தையே அளவுகோல்; ஆகவே நான் பரமஹம்ஸ ஆசிரமத்தை ஏற்றுப் பற்றின்மையை வெளிப்படுத்துவேன்.”',
        '0.2': '“மேலும், விஷ்ணுவை வெறுப்போர் விஷயத்தில் தண்டத்தை (தண்டனையை) ஏந்தாமல் இருப்பது என் இறைவனின் பணிக்குப் பொருந்தாது; ஹரியின் தங்கை துர்க்கை விரைவில் தீயோரை அழிக்கத் துணை புரிவாள்; ஆகவே நான் வெறும் தண்டதாரி அல்லன்.”',
        '0.3': 'இவ்வாறு சிந்தித்து, அனந்தனைத் தியானிப்பவரும் முழுத் துறவில் உறுதியான முடிவு கொண்டவருமான அவர், அனுமதிக்காக எங்கும் நிறைந்தவனும் தன்னையே அளிப்பவனுமான ஹரியை வணங்கினார்.',
        '0.4': '“உன்னுடையவனை ஏன் வணங்குகிறாய்?” என்று கேட்கப்பட்டபோது “என் சொந்தப் பொருளையே வணங்கினேன்” என்று கூறி, எல்லா உலகுக்கும் ஆசானான ஜகத்குரு அப்போது குருவைத் தேடிப் புறப்பட்டார்.',
        '0.5': 'பூமியில் பெரும் வைராக்கியத்தையே அணிகலனாகக் கொண்ட புலனடக்கமுள்ள ஒரு யதி இருந்தார்; பெயரால் மட்டுமின்றிப் பொருளாலும் தூயவரான அவரை மக்கள் “அச்யுதப்ரேக்ஷர்” என்று அழைத்தனர்.',
        '0.6': 'முன்பு பாண்டவர்களின் ஒரு கோயிலில் கிருஷ்ணையின் (திரௌபதியின்) கையால் தூய்மையான சிறந்த உணவை உண்டு மனத் தூய்மை பெற்ற அவர், தேனீ போன்ற பிச்சை வாழ்வால் சில ஆண்டுகள் மகிழ்வுடன் திரிந்தார்.',
        '0.7': 'மரபில் வந்த தவறான சாஸ்திரப் பயிற்சி அந்த யதிக்குப் பாவமாகவில்லை, ஏனெனில் காலப்போக்கில் அவருக்கு மனவருத்தம் உண்டானது — முராரியின் திருவடித் தாமரையில் வேடன் அம்பு எய்தது அவன்மீது குற்றமாகாதது போல.',
        '0.8': 'தம் மரணம் நெருங்கியதை அறிந்த குரு, ஒருமுறை அடக்கமுள்ளவரும் உபநிஷத்துக்களில் வல்லவரும் எப்போதும் உண்மையை அறிய விரும்புபவருமான அவரிடம் தனிமையில் இந்தச் சொல்லைக் கூறினார்.',
        '0.9': '“‘உணர்வு தெளிவாக ஒளிரும்போது நானே பிரம்மம், எனக்கு அப்பால் எதுவும் இல்லை’ என்று மாயாவாதத்தில் நிறுவப்பட்டது ஆதாரமற்றது; நல்விரதனே, அதை நம்பாதே.”',
        '0.10': '“உபாசனைக்கு விதிக்கப்பட்ட இந்த ஆத்ம ஐக்கியம் என் குருவுக்கும் நேரடி அனுபவமாகவில்லை; அன்பனே, பண்டையோருக்கும் எங்கும் ஆகவில்லை; ஆகவே ஞானத்திற்காக மகிழ்வுடன் முகுந்தனை வழிபடு.”',
        '0.11': 'இந்த உபதேசத்தைச் செய்து சொல்வன்மையுள்ள தம் குரு பரலோகம் சென்றபின், அவர் குருவின் சொல்லை மீண்டும் மீண்டும் சிந்தித்தவாறு ரூப்யபீடத்தில் வாழும் இந்திராபதியை வழிபட்டார்.',
        '0.12': 'பரம்பொருளை அறிய விரும்பிய அந்த நல்ல பக்தரால் அங்கே வழிபடப்பட்ட பக்தவத்சலன், ஒரு மனிதனுள் ஆவேசித்து “வரப்போகும் சிறந்த சீடன் மூலம் என்னை அறிவாயாக” என்று அவரிடம் கூறினான்.',
        '0.13': 'அந்த அருளை மகிழ்வுடன் எதிர்நோக்கித் தாமரைக் கண்ணனை மீண்டும் மீண்டும் வழிபட்டிருந்த அமைதியான அந்த யதியிடம், ஒரு நோக்கத்திற்காக மனித வடிவம் கொண்ட நல்லோரின் குரு வந்து சேர்ந்தார்.',
        '0.14': 'பற்றற்ற தம் மகன் யதீந்திரரின் சீடனாகித் துறவில் மனம் வைத்திருப்பதைக் கேட்டு, பிரிவால் வாடிய பாசமுள்ள பெற்றோர் ரூப்யபீடத்தில் இருந்த அவனிடம் வந்தனர்.',
        '0.15': '“மகனே, முதியோரும் ஆதரவற்றோருமான நாங்கள் இருவரும் உயிரோடிருக்கும் வரை உனக்கு உயர்ந்த ஆசிரமம் வேண்டாம்” என்று கெஞ்சிக் கூறி, அவர்கள் மகனை வலம் வந்து வணங்கினர்.',
        '0.16': 'அந்தப் பிரபு கூறினான்: “சேவை செய்ய விரும்புபவனை வணங்குவது முறையல்ல; ஆயினும் நீங்கள் இப்போது தெளிவாக வணங்கிவிட்டீர்கள்; ஆஹா! விதாதாவே உங்களைக் கொண்டு அனுமதி அளிக்கச் செய்தான்!”',
        '0.17': 'பதில் தெரியாமல் அவர் மீண்டும் வேண்டி, யதீந்திரரை வணங்கி மனைவியுடன் புறப்பட்டார்; வீட்டில் இருந்தவாறு கல்பங்கள் போன்ற கணங்களைக் கழித்து, மகனின் முகச்சந்திரனை இடைவிடாமல் நினைத்தார்.',
        '0.18': 'மகனின் தீர்மானத்தைத் துயருடன் எண்ணியவாறு அவர் மீண்டும் பெருநதியைக் கடந்து வந்து, ஒரு சிறந்த கிராமத்தின் மடத்தில் யதீஸ்வரரைப் பின்பற்றியிருந்த தன் மகனைக் கண்டார்.',
        '0.19': 'மகான்களை மீறுவதற்கு அஞ்சுபவராக இருந்தும், கோபத்தால் கலங்கிய அந்த அந்தணர் “என் மகன் கௌபீனம் அணிந்தால், ஏதேனும் துணிகரச் செயல் செய்வேன் என்ற என் சபதம் உறுதி” என்றார்.',
        '0.20': 'ஒரு கணத்தில் அந்தப் பிரபு தன் ஆடையைக் கிழித்துக் கௌபீனம் அணிந்து, “அப்பா, உங்கள் துணிகரச் செயலைச் செய்யுங்கள்” என்று கூறி, மீண்டும் “நீங்கள் நன்மைக்குத் தடை செய்யக்கூடாது” என்றான்.',
        '0.21': '“மகனே, பெற்றோரைக் காக்காமல் நன்மை இல்லை என்று நல்லோர் சொல்கின்றனர்; நீ விலகினால் எங்களுக்குக் காப்பவர் இல்லை; நாங்கள் இருவரும் இறந்தவர்களுக்குச் சமம்” என்ற தந்தையிடம் மகன் கூறினான்:',
        '0.22': '“மனிதன் பற்றற்றவனாகும்போதே சந்நியாச விதி என்று சுருதியில் கேட்கப்படுகிறது; ஆயினும் பற்றற்றவனாக இருந்தும், உங்கள் இருவருக்கும் சேவை செய்ய ஒருவரை ஏற்பாடு செய்யாமல் நான் துறவு கொள்ளமாட்டேன்.”',
        '0.23': '“நிறைய கற்றவனானதால் நான் வலுக்கட்டாயமாகப் பொறுத்துக்கொள்வேன்; ஆனால் உன் தாய் உன் பிரிவைத் தாங்கமாட்டாள்” என்று அந்தணர் கூற, “நீங்கள் அனுமதி தாருங்கள்” என்று சொல்லி அவன் தந்தையை வணங்கினான்.',
        '0.24': 'சிந்தித்துப் பதில் இல்லாமல் போன அந்த அறிஞர் “அப்படியே ஆகட்டும், தாய் ஒப்புக்கொண்டால்” என்று சிரமத்துடன் கூறி, வீடு சென்று மனைவியிடம் அந்தச் செய்தியைச் சொன்னார்.',
        '0.25': 'முன்பு அரக்கர்களின் பகைவனான ராமனுக்கு லக்ஷ்மணன் போலவும், விருகோதரனுக்கு இந்திரன் மகன் அர்ஜுனன் போலவும், சௌரிக்குக் கதன் போலவும், அந்தச் சர்வஞ்ஞருக்குப் பணி செய்யும் அன்பும் பக்தியுமுள்ள தம்பி பிறந்தான்.',
        '0.26': 'ஒருமுறை வீட்டுக்கு வந்து இந்தத் தம்பியையே அவர்கள் இருவரையும் காப்பவனாகக் காட்டி, தம் துறவைத் தடுப்பதில் உறுதியாக இருந்த தாயிடம் தந்தையின் அனுமதியுடன் அவர் இவ்வாறு கூறினார்.',
        '0.27': '“அம்மா, என்னை எப்போதாவது பார்க்க விரும்பினால், நான் உயர்ந்த ஆசிரமத்தை ஏற்க ஒப்புக்கொள்; இல்லையெனில் இந்த நாட்டையே விட்டுச் சென்று உங்கள் கண்ணில் ஒருபோதும் படமாட்டேன்.”',
        '0.28': 'மகன் இவ்வாறு சொல்ல, அவனை ஒருபோதும் காணாமல் இருப்பது அவன் மரணத்துக்குச் சமம் என்று எண்ணி மிகவும் கலங்கிய அந்த நல்லவள், சிரமத்துடன் மகனின் விருப்பத்தைத் தடுக்கவில்லை.',
        '0.29': 'பிறகு தேவர்களில் சிறந்தவனின் அருளுக்குரிய அந்த ஜகத்குரு, குருவை அணுகி அவரை மகிழ்வித்தார்; எப்போதும் எல்லா ஆசிரமங்களுக்கும் உரிய அந்தச் சுரேஸ்வரர் சிறப்பாக உயர்ந்த ஆசிரமத்தை ஏற்றார்.',
        '0.30': 'காலத்தை அறிந்த அவர் எல்லாச் சடங்குகளையும் விதிப்படியே செய்து, எப்போதும் மகிழ்ந்திருக்கும் ஹரியின் மகிழ்ச்சிக்காக மீண்டும் மீண்டும் முழுத் துறவை அறிவித்தார்.',
        '0.31': 'மூன்று மாத்திரைகளில் தொடங்கி அனந்த மாத்திரைகளில் முடிவதாக ஞானிகள் கூறும் பிரணவத்தின் ஜபத்திற்கு உரியவராக, எதிர்கால நான்முகப் பிரம்மனின் வடிவுடைய இந்த யதி அப்போது சுட்டிக்காட்டப்பட்டார்.',
        '0.32': '“குணங்களுக்கு ஏற்ற உயர்வுடைய பூர்ணபோதர் (பூர்ணப்ரஜ்ஞர்)” என்ற பெயரை அந்தணர் கூட்டத்தால் வணங்கப்பட்ட அந்தப் புகழ்மிக்க குரு அவருக்குச் சூட்டினார்; அது வெறும் மந்திர எழுத்தல்ல, அவரே மந்திரங்களை விளக்குபவர்.',
        '0.33': 'உடல் பூச்சும் முகச் சாயமும் இல்லாத, தம் அணியே உலகுக்கு அணியான, பலாச தண்டம் ஏந்திய அவரைக் கண்டு, இயற்கை அழகே ஒப்பற்றது என்று உயிர்கள் எண்ணின.',
        '0.34': 'சேஷன், ருத்திரன், கருடன் முதலானோர் தருணம் பார்த்து அவரை வணங்கியபோதும், அவர் குரு முதலான யதிகளை வணங்கினார் — ஆஹா, மகான்களின் நடிப்பு எவ்வளவு பெரியது!',
        '0.35': 'உயர்ந்த ஆசிரமத்தின் சிறப்பு ஒழுக்கத்தைக் கற்பிக்க விரும்பிய அவருடைய நடத்தையைக் கண்டு, உறுதியான அறிவுடைய யதீஸ்வரர் தாமே சிறப்புப் பயிற்சி பெற்று உள்ளுக்குள் வியந்தார்.',
        '0.36': 'பேரறிவாளரான அவர் ரௌப்யபீடத்தில் வாழும் இறைவனை மகிழ்வுடன் வணங்கியபோது, அரவணையில் துயிலும் அந்தத் தேவன் ஒரு மனிதனுள் ஆவேசித்து உடனே தன் கையால் அவர் கையைப் பற்றினான்.',
        '0.37': '“நெடுங்காலமாக உண்மையை அறிய விரும்பி நீ செய்த என் சேவையின் பலனாக இவரை உனக்குக் கொடுக்கிறேன்” என்று கூறி, அந்த இறைவன் அவரை அழைத்துச் சென்று அச்யுதப்ரேக்ஷரிடம் ஒப்படைத்தான்.',
        '0.38': 'அந்த அருளை மரியாதையுடன் ஏற்று, தாம் பெற்ற நிறைவை மகிழ்வுடன் நினைத்து, பற்றற்றவராக இருந்தும் அந்தக் குரு அவர்மீது பற்றுக் கொண்டார்; பற்றற்றோருக்கு நல்லோர் சேர்க்கையே அணிகலன் அல்லவா!',
        '0.39': 'பெருமனமுடைய அவர் வான்கங்கைக்குச் செல்ல விரும்பி அனுமதிக்காக மீண்டும் மீண்டும் வணங்க, வரப்போகும் பிரிவு என்னும் நெருப்பின் அச்சத்தால் வருந்திய குரு தம் இறைவனையே நினைத்தார்.',
        '0.40': 'அப்போது கருணைக் கடலான ஹரி ஒருவனுள் ஆவேசித்து அவரிடம் கூறினான்: “இன்றிலிருந்து மூன்றாம் நாள் வான்கங்கை உனக்காக நம் குளத்திற்கு வருவாள்; ஆகவே போகாதே.”',
        '0.41': 'அவனுடைய ஆணைப்படி வந்த கங்கை நீரில் மக்கள் பூர்ணபுத்தியுடன் அங்கே நீராடினர்; அன்றிலிருந்து அவன் அருளின் அடையாளமாகப் பன்னிரண்டு ஆண்டுகளுக்கு ஒருமுறை அவள் எப்போதும் வருகிறாள்.',
        '0.42': 'உயர்ந்த ஆசிரமத்தை அடைந்து பத்து நாட்கள் கழிந்ததும், சவால் பத்திரத்தைத் தொங்கவிட்டு, பல தர்க்கங்களால் கடுமையான வெற்றியாளர்களான வாசுதேவ பண்டிதர் முதலானோரை அவர் வென்றார்.',
        '0.43': 'தம் சீடனைத் திறமையானவனாக்க விரும்பிய குருவின் தூண்டுதலால், அந்த மகான் மதிப்பின்றியும் சலம், ஜாதி (குதர்க்கங்கள்) என்பவற்றின் கடலான “இஷ்டஸித்தி”யை இங்கே கேட்கத் தொடங்கினார்.',
        '0.44': 'அதன் முதல் செய்யுளிலேயே முப்பத்திரண்டு குறைகளின் தொகுதியை அவர் சுட்டிக்காட்ட, “அது பின்னால் மறுக்கப்பட்டுள்ளது” என்று குரு கூறியபோது, “அப்படியானால் அது சொல்லப்படட்டும்” என்று அவர் கூறினார்.',
        '0.45': '“உனக்கு விளக்கும் திறன் எனக்கில்லை” என்று யதீஸ்வரர் கோபத்துடன் கூற, மாயாவாதத்தில் வல்லவர்களிடமும் அதன் குறைகள் பற்றிய ஐயத்தின் முளை தோன்றியது.',
        '0.46': '“ஞானி உபதேசிக்க வேண்டும், முக்தியை நாடும் அறியாதவன் நிச்சயம் கேட்க வேண்டும், யதி சிறப்பாக” என்ற மக்களின் வேண்டுகோளால் பூர்ணதீ மாயாவாதத்தை விளக்கினார்.',
        '0.47': 'இடையறாத விளக்கமும், ஐயமின்மையும், மரபு ஒழுங்கும், உறுதியான பதில்களும் கொண்ட அவருடைய பிரவசனத்தைக் கேட்க, கற்றவர்களும் திறமையானவர்களும் முன்னேற விரும்பியவர்களுமான மக்கள் ஆர்வத்துடன் வந்தனர்.',
        '0.48': 'ஒருமுறை குருவின் அருகே பாகவதம் கேட்டுக்கொண்டிருந்த ஐந்தாறு அந்தணர்கள் பல பாட பேதங்களுடன் எழுதப்பட்ட ஒரு பகுதியைப் படித்தபோது, அந்தப் பிரபு ஒரு பாடத்தை உறுதியாகக் கூறினார்.',
        '0.49': '“வேறு பாடங்களும் சாத்தியமாக இருக்க, நீ இதையே எப்படி நிர்ணயிக்கிறாய்?” என்று கேட்கப்பட, அந்தப் பெருமனத்தவர் முகுந்த ஞானத்தால் பகவான் (வியாசர்) இயற்றிய ஒரு பாடத்தைத் தெளிவாகக் கூறினார்.',
        '0.50': '“ஜகத்குருவின் படைப்பின் நிலையை நீ அறிவாயானால், இங்கேயே ஐந்தாம் ஸ்கந்தத்தின் உரைநடைப் பகுதியைச் சொல்” என்று யதிகளில் சிறந்தவர் கூற, அந்தப் பெருமனத்தவர் தாம் சொன்ன முறையிலேயே அதைச் சொன்னார்.',
        '0.51': 'அப்போது அவருடைய ஆணையால் எல்லாச் சீடர்களும் சோதனைக்காக எல்லாச் சுவடிகளையும் பார்த்தனர்; அவற்றுள் ஒன்றில் மட்டுமே இருந்த அத்தியாயத் தொகுதியை அவர் விட்டுவிட்டுச் சொல்லியிருந்தார்.',
        '0.52': '“வெற்றியாளனே, இந்தப் பிறவியில் நீ படிக்காதது உனக்கு எப்படித் தோன்றுகிறது?” என்று அவர் கேட்க, “முற்பிறவிகளில் இவை அனைத்தையும் முன்பே அறிந்திருந்தேன்” என்றார் அளவற்ற அறிவாளர்.',
        '0.53': 'இவ்வாறு உலகையே வியக்கச் செய்த பல மனச் செயல்களால் அவருடைய புதிய புகழ் உலகில் பரவியது — பரந்த இருளை அழிக்கும் சூரிய ஒளி போலவும், நல்லோராகிய அல்லி மலர்களுக்கு ஆனந்தம் தரும் நிலவொளி போலவும்.',
        '0.54': 'இவ்வாறு கவிகுலத் திலகரான த்ரிவிக்ரம பண்டிதாசாரியரின் மகன் நாராயண பண்டிதாசாரியர் இயற்றிய, “ஆனந்த” என்ற முத்திரை கொண்ட ஸ்ரீமத் ஸுமத்வ விஜய மகாகாவியத்தின் நான்காம் சர்க்கம் நிறைவுற்றது.',
      },
    },
    'sumadhva-vijaya-05': {
      verses: {
        '0.0': 'வேதாந்த வித்யை என்னும் தம் அரசைக் காக்கும் பெரும் பொறுப்புக்குக் குருவால் தேர்ந்தெடுக்கப்பட்ட அந்தப் பரந்த உள்ளத்தவர், தாமரைகள் நிறைந்த நீரால் அபிஷேகம் செய்யப்பட்டார்.',
        '0.1': 'ஆனந்த வடிவான பரம்பொருளுக்கு உரிய பாத்திரமும், ஆனந்தம் தரும் நல்ல சாஸ்திரங்களை இயற்றுபவருமாக இருந்ததால், குரு சூட்டிய “ஆனந்ததீர்த்தர்” என்ற பெயர் அவருக்கு மிகப் பொருத்தமானதாயிற்று.',
        '0.2': 'ஒருமுறை அச்யுதப்ரேக்ஷரின் நண்பரான ஒரு யதி பல சீடர்களுடன் அங்கே வந்தார்; அனுமான சாஸ்திரத்தில் பயிற்சி பெற்ற அவருடைய செருக்குள்ள சீடர்கள் பேரறிவாளரான மத்வரை வெல்ல விரும்பினர்.',
        '0.3': '“வேறுபாட்டை நிறுவ முடியாது” என்ற, எதிர்த்தரப்புக்கு அச்சமூட்டும் அனுமானத்தை அவர்கள் விரைவில் முன்வைத்தனர்; தரப்பை நிறுவுவதில் வல்ல அகண்ட அறிவாளர், பறவையரசன் பாம்பைக் கிழிப்பது போல் அதைத் தெளிவாக மறுத்தார்.',
        '0.4': 'பிறகு அவர்கள், “சர்ச்சைக்குரிய உலகம் பொய், ஏனெனில் அது அறிவுக்குப் பொருளாகிறது, சர்ச்சையற்ற (சிப்பியில் வெள்ளி போன்ற) பொருளைப் போல” என்றனர்; அவர் “சர்ச்சைக்குரியது உண்மை, ஏனெனில் அது உண்மையாக அறியப்படுகிறது, குடம் முதலியவை போல” என்ற அனுமானத்தைக் கூறினார்.',
        '0.5': 'அவர்கள் ஆர்வத்துடன் அவருடைய ஏதுவில் அதிவ்யாப்தி குற்றம் சுமத்தியபோது, கலங்காத அவர் உடனே “சிப்பி-வெள்ளி முதலியவை உண்மையாக அறியப்படுவதில்லை; வேறு விதமாக அறியப்படுவது வேறு” என்பன போன்றவற்றைக் கூறி அவர்களை வென்றார்.',
        '0.6': 'சர்ச்சைக்குரிய விஷயத்தில் உண்மைக்கும் பொய்மைக்கும் அனுமானங்களைக் கூறி, அங்கே அனுமானம் மட்டுமே முடிவானதல்ல என்று தாமே நிறுவி, சபைகளில் எல்லா அறிஞர்களையும் வென்று அவர் “அனுமானதீர்த்தர்” என்ற பெயரையும் பெற்றார்.',
        '0.7': 'பிறகு எதிராளிகளைத் தேடிப் பூமியில் திரிந்தவனும், வாதத் தலைவர்கள் என்னும் யானைகளை முறிப்பவனும், வேத எதிர்ப்பாளர்களில் முதன்மையானவனுமான புத்திஸாகரன் வாதிஸிம்ஹனுடன் இங்கே வந்தான்.',
        '0.8': 'வலிமையான கோட்டையின் செருக்குடைய அவனை வெல்ல விரும்பி, முகுந்தனில் மனம் வைத்த குரு, தம் சீடனின் கையால் மடம் என்னும் அம்பறாத்தூணியிலிருந்து நல்ல இறகுடைய கூர்மையான ஸுகதீர்த்தர் (ஆனந்ததீர்த்தர்) என்னும் அம்பை விரைவில் எடுத்தார்.',
        '0.9': 'வாதத்தில் ஆர்வமுள்ள மக்கள் கூட்டம் விரைந்து கூடியதைக் கேட்டு, மிகச் சிறந்த அறிவுடைய அவர் வந்து ரூப்யபீடத்தின் சிறந்த கோயிலில் இருந்த குருவை வணங்கினார்.',
        '0.10': 'அறிஞர் வட்டத்தின் நடுவே அவர் வாதிஸிம்ஹனின் கனமான சொற்களைக் கூர்மையான, அளவான, வேகமான வாக்கியங்களால் மீண்டும் மீண்டும் மறுத்தார் — திறமையான வில்லாளன் அம்பால் கதையைத் துண்டிப்பது போல.',
        '0.11': 'பிறகு மற்றவன் (புத்திஸாகரன்) பொறாமையால் ஒரு விஷயத்தைப் பதினெட்டு விதமாக உரக்க முன்வைத்தான்; அப்போது உலகை வென்ற பூர்ணப்ரஜ்ஞரின் வெற்றி பற்றி மக்களுக்குச் சற்று ஐயம் உண்டானது.',
        '0.12': 'பிறகு எண்ணற்ற மாற்று வாதங்களை விரைவில் மறுத்தவாறு அந்தப் பேரறிவாளர் புன்னகை முகத்துடன் மேலும் ஒளிர்ந்தார் — தூய கதிர்களால் இருள் குவியல்களை அழித்து வானில் (விஷ்ணுபதத்தில்) நிலைத்திருக்கும் சூரியனைப் போல.',
        '0.13': 'கடலைக் குடித்த கும்பத்தில் பிறந்த அகஸ்தியரைப் போல், பெருமனமுடைய அவர் தன் பார்வையில் ஆழங்காணமுடியாததும், கரை மீறியதும், செருக்குடையதும், பிற கல்வி நதிகளை எல்லாம் இகழ்ந்ததுமான அந்த “புத்திஸாகரனை” எளிதாகச் சிறுமைப்படுத்தினார்.',
        '0.14': '“நாளை வாதம் தொடரட்டும்” என்று அந்த இரு தீய வாதிகள் கூற, “பதில் தோன்றினால் இன்றே சொல்லுங்கள்” என்று மத்வர் சொன்னபோது, மக்கள் அவர்கள் தோற்றனர் என்று கருதினர்; இரவில் அவர்கள் ஓடிவிட்டதால் அதை உறுதிசெய்தனர்.',
        '0.15': '“ஆஹா! புத்திஸாகரனும் அந்த வாதத் தலைவனும் நெடுங்காலம் பூமியைச் சுற்றி ஈட்டிய வெற்றித் திருவை இவர் முயற்சியின்றி ஒரு கணத்தில் பெற்றுவிட்டார்!” என்று மக்கள் பெரிதும் வியந்தனர்.',
        '0.16': 'ஒருமுறை தர்க்கத்தில் வல்லவர்களால் சூழப்பட்டு, மணிமான் (கவியின்படி) இயற்றிய பாஷ்யத்தை விளக்கிக்கொண்டிருந்தபோது, ஆனந்ததீர்த்தர் கேலிச் சிரிப்புடன் தேவர்களுக்கு மகிழ்ச்சி தரும் சொல்லைக் கூறினார்.',
        '0.17': '“தூய அறிவுடையோர் கடுமையான மறைந்த பிடிவாதத்தை விட்டுச் சூத்திரங்களின் உண்மைப் பொருளையும் பாஷ்யத்தின் நோக்கத்தையும் தனித்தனியே ஆராய்ந்தால், ஆஹா, இவ்விரண்டுக்கும் இடையே மதிக்கத்தக்க பொருத்தம் காணப்படுவதில்லை.”',
        '0.18': 'இவ்வாறு கூறி அந்தப் பாஷ்யத்தில் வலுவான குறைகளை மீண்டும் மீண்டும் காட்ட, வியந்திருந்தும் அவர்கள் முயன்றும் அவற்றை உறுதியாக நீக்க முடியவில்லை.',
        '0.19': 'அந்தச் சொல்வன்மையாளர்கள் கூறினர்: “நீங்கள் பாஷ்யத்தை மட்டுமே மறுப்பதால், உங்களைப் போன்ற கவிகளாலும் எவ்விதத்திலும் குறைகூற முடியாத இந்தச் சூத்திரத்தின் வேறு பொருளைச் சொல்லுங்கள்.”',
        '0.20': 'அப்போது அவர், இயல்பான சொல்லமைப்பு உடையதும், பிரமாணமாக்கப்பட்ட வேதங்களும் ஸ்மிருதிகளும் கொண்டதும், விரைவில் வரவிருக்கும் பாஷ்யம் என்னும் நடனத்துக்குச் சூத்திரதாரி போன்றதுமான சாத்தியமான சூத்திரப் பொருளை உரக்கக் கூறினார்.',
        '0.21': 'அறியும் விருப்பத்துடன் வந்த பொறாமையற்றவர்களானாலும், வெல்லும் விருப்பத்துடன் வந்த பொறாமையாளர்களானாலும், சாஸ்திரங்களில் வல்லவர்களும் பெரும் தர்க்கவாதிகளுமான அவர்களை அவர் இந்த முறையால் மீண்டும் மீண்டும் தோற்கடித்தார்.',
        '0.22': 'ஒருமுறை அமைதியான மனமுடைய சிறந்தவரான மத்யகேஹர் அவரிடம் வந்து மகிழ்ந்தார்; ஏதோ காரணத்தால் வருந்தியிருந்தாலும், குணக் கடலை நாடும் நல்லவன் மகிழ்ச்சியடைகிறான் அல்லவா!',
        '0.23': 'அந்த அறிஞர், மகனின் உடல் என்னும் பாத்திரத்தில் இருந்த அழியாத ஒளி அமுதத்தைக் கண்கள் என்னும் கைக்குழிவுகளாலும், அவருடைய சொல் என்னும் பெருங்கலசத்தில் நிறைந்த கல்வி அமுதத்தைச் செவிகள் என்னும் கிண்ணங்களாலும் பருகினார்.',
        '0.24': 'விளையாட்டு வாதத்தில் அப்படி ஒரு தருணம் வந்தபோது, குரு சற்று சவாலாக “சூத்திரப் பொருளை நீ அறிவாயானால் உடனே பாஷ்யம் இயற்று” என்று ஜகத்குருவிடம் கூறினார்.',
        '0.25': 'அன்னவரசு நீரிலிருந்து தூய பாலை மட்டும் எடுப்பது போல், அந்தப் பரமஹம்ஸர் அப்போது ஆணையை மட்டும் ஏற்று, அதில் கலந்த பயனற்ற குத்தலை நீரைப் போல் புறக்கணித்தார்; நல்லோர் குணத்தின் பகுதியாலேயே மகிழ்கின்றனர்.',
        '0.26': 'ஒருமுறை வைராக்கியம், துணிவு, நல்ல சொல்வன்மை முதலிய பரமஹம்ஸ அணிகலன்களான குணங்கள் கொண்ட, லிகுச குலத்தில் பிறந்த மூத்த யதி பெரும் பக்தியுடன் அவரிடம் கூறினார்:',
        '0.27': '“இந்தப் பாஷ்யம் முதலியவை வேதாந்த முடிவுகளின் செல்வத்திற்கு எதிரானவையானால் ஆகட்டும், என்ன இழப்பு? சூத்திரங்களும் உபநிஷத்துக்களும் கருதிய பொருளை விவேகிகளுக்குத் தகுந்தபடி எங்களுக்குச் சொல்லுங்கள்.”',
        '0.28': 'அவருடைய சொல்லால், கூதிர்காலத்தால் போல், எல்லாத் திசைகளும் நன்மையால் நிறைந்து ஒளிர்ந்தபோது, விஷ்ணுபதத்தை (வானை/விஷ்ணு தத்துவத்தை) ஒளிரச் செய்யும் “வ்யாக்யானம்” என்னும் ஆனந்ததீர்த்தரின் முகச்சந்திர நிலவொளி வெளிப்பட்டது.',
        '0.29': 'ஒருமுறை யமனால் காக்கப்படும் தெற்குத் திசையை வெல்ல அச்யுதப்ரேக்ஷருடன் புறப்பட்ட முழு அறிவாளர், விஷ்ணுமங்கலத்தில் அந்த இடத்தை அலங்கரிக்கும் உலக மங்களமான விஷ்ணுவை வணங்கினார்.',
        '0.30': 'அங்கே பிச்சை அளித்தவர் சோதிப்பதற்காக மீண்டும் மீண்டும் வாழைப்பழக் குவியலைக் கொடுக்க, அவர் சிரமமின்றி அவை அனைத்தையும் உண்ண, வியப்பை அடக்க முடியாத குரு தனிமையில் அந்தச் சிறந்த ஆரியரிடம் கூறினார்:',
        '0.31': '“உணவின் முடிவில் நீ உண்ட இருநூறுக்கும் மேற்பட்ட பழங்களால் நிறைந்திருந்தும் உன் மெல்லிய வயிற்றில் கனமே இல்லை; இது எப்படி? நல்லுள்ளத்தவனே, உண்மையைச் சொல்.”',
        '0.32': 'அப்போது உலகநாதனில் மனம் வைத்த அவர் கூறினார்: “என் வயிற்றில் கட்டைவிரல் அளவான, கொழுந்துவிட்டு எரியும், எப்போதும் நன்மை செய்யும், அனைத்தையும் எரிக்கும் அக்னி உள்ளது என்று அறியுங்கள்.”',
        '0.33': 'கொந்தளிக்கும் பல நதிகளைக் கொண்ட நாடுகளையும், தர்க்கம் நிறைந்த பல பொருள்களைக் கொண்ட மதங்களையும் கடந்து, அந்த அழகிய அறிவாளர் தாம் தேர்ந்த வழியில் சென்றார்.',
        '0.34': 'வழியில், விளையாட்டாக மர வரிசைகளைச் சாய்ப்பதும், மனத் தூய்மை தருவதும், கேரளத்தின் அணிகலனும், அந்தணர்களால் வழிபடப்படுவதுமான பயஸ்வினீ நதியைக் கண்டு, அவர் அங்கே தோன்றவிருக்கும் சண்டிகையை நினைத்தார்.',
        '0.35': 'பிறகு படிப்படியாகச் சென்று புனித அனந்தபுரத்தை (அனந்தசயனத்தை) அடைந்து, நீலத் தாமரை போன்ற அழகிய ஒளியுடைய, அரவணையில் துயிலும் பத்மநாபனான ஸ்ரீபதியை வணங்கினார்.',
        '0.36': 'முடிவான உண்மைகளை அறிந்தோரில் சிறந்த அவர், சபையில் சீடர்களுக்கு வேதாந்த சூத்திரங்களை விளக்கி, குணக் கடலான அச்யுதன் என்னும் பிரம்மம் உயிர்க் கூட்டத்திலிருந்து வேறுபட்டது என்று மீண்டும் மீண்டும் நிறுவினார்.',
        '0.37': 'அப்போது அப்ராம்சுநூதனம் என்ற இடத்தில் பிறந்த, பகைமையில் ஈடுபட்ட ஒரு “சங்கரன்” (குழப்புபவன்) பொறாமையுடன், “பாஷ்யம் இயற்றாதவர்கள் சூத்திரப் பொருளைக் கூறுவது பெரும் மீறல்” என்றான்.',
        '0.38': '“பதில் தோன்றினால் சொல்; நாங்கள் இங்கே பாஷ்யம் இயற்றுவோம்; ஜகத்குருக்களான தண்டதாரிகளுக்கு நூல் இயற்றுவது தடுக்கப்படவில்லை” என்ற குருவின் புன்னகைச் சொல்லை மக்கள் அனைவரும் போற்றினர்.',
        '0.39': 'அறிஞர்கள் அந்தப் பிரபுவின் உடல் மகாபுருஷ லக்ஷணங்கள் அனைத்தும் கொண்டது என்று கூற, பிறர் அவருடைய இடுப்பின் மிகுந்த பருமனை மட்டுமே (குறையாக) எடுத்துக் கூறினர்.',
        '0.40': 'நிறைந்த சபையில் லக்ஷண சாஸ்திரத்தின் அடிப்படையில் இடுப்பின் குறைகளை அந்த விமர்சகன் விரிவாகக் கூறிப் பதில் பெற்றபோது, அதைத் தாங்க முடியாமல் மத்வரின் தண்டத்தை முறிப்பதாகச் சபதம் செய்தான் — தீயோரின் இயல்பே அது.',
        '0.41': 'அங்குள்ள தீர்த்தங்களில் நீராடி, விரைவில் சிறந்த தீர்த்தமான கன்யாதீர்த்தத்தில் (கன்னியாகுமரியில்) ஸுகதீர்த்தர் மூழ்கி, கடல் சேதுவிலும் நீராடி, விஷ்ணுவான ஸ்ரீராமநாதனை வணங்கினார்.',
        '0.42': 'யதி வேடம் பூண்ட அந்த அசுரத்தன்மை கொண்டவன் வர, அவர் தண்டத்தைக் காட்டிச் சிரித்தவாறு கூறினார்: “கடுமையானவனே, உன்னால் இந்தத் தண்டம் முறிக்கப்படாவிட்டால் நீ ஆண்மையற்றவன், அறிவற்றவன், பயனற்ற சொல்லுடையவன்.”',
        '0.43': 'வெட்கத்தால் தலைகுனிந்து தன் சுயநலத்தை நாடிய அந்தத் தீயவனை அப்போது அந்தணத் தலைவர்கள் புறக்கணித்தனர்; “முகச்சந்திரனால் உலகை மகிழ்விக்கும் அந்த அறிஞரை இங்கே யார் வெறுப்பார்?” என்றனர் வாதிகள்.',
        '0.44': 'அவரைச் சந்தித்த பல்வேறு கல்வி வல்லுநர்கள் சபைகளில் எந்த எந்தக் கலைகளை எழுப்பினரோ, அவை அனைத்திலும் ஒளிமிக்க அந்தக் கல்வித் தலைவர் விளங்கி அவர்களை வென்றார்.',
        '0.45': 'இங்குள்ள வலிமையற்ற தீயோரின் சேட்டைகளால் அசையாத அந்தப் பெருமனக் குரு, நாய்களிடையே குகைக்குள் சென்ற சிங்கம் போல நான்கு மாதங்கள் (சாதுர்மாஸ்யம்) அங்கே தங்கினார்.',
        '0.46': 'கூர்மையான அறிவுடைய அவர் ஸ்ரீரங்கத்திற்கு வந்து, அழகுக் கடலும், நல்லோருக்கு மங்களம் அருள்பவனும், காவேரியின் குளிர்ந்த காற்றால் சேவிக்கப்படுபவனுமான அரவணையில் துயிலும் தேவனை வணங்கினார்.',
        '0.47': 'பிறகு திரும்பி, பல கோயில்களில் சஞ்சரித்துப் பரம புருஷனை வணங்கி, தம் மனிதனுக்கு அப்பாற்பட்ட மேன்மைகளை வெளிப்படுத்தியவாறு அவர் படிப்படியாக வடக்குத் திசை நோக்கிச் சென்றார்.',
        '0.48': 'ஆங்காங்கே வியந்த கண்களுடைய மக்களால் பார்க்கப்பட்டவாறு, மிகச் சிறந்த லக்ஷணங்கள் கொண்ட வடிவுடைய அவர் பயஸ்வினீ கரையிலுள்ள சிறந்த கிராமங்களை அடைந்து ஒரு கோயிலில் நுழைந்தார்.',
        '0.49': 'முறைப்படி ஆறு அங்கங்களுடன் வேதத்தைக் கற்று, அதன் பொருள் விளக்கத்தை நிர்ணயிக்கத் தெரிந்த சிறந்த அந்தணர்கள், உலகைக் கரையேற்றுவதில் புகழ்பெற்ற அந்த அரிய மனிதரை அறிய விரும்பி வந்தனர்.',
        '0.50': 'புன்னகை நிலவும், தாமரைக் கண்களும், பொன்னிறமும், மிக மங்களமான சொல்லும் உடையவரும், அணிகலன்கள் இல்லாதிருந்தும் உலகின் அணிகலனுமான அவரைக் காண விரும்பி மக்கள் திரளாகக் கூடினர்.',
        '0.51': 'கல்வியால் ஒளிரும் விண்மீன்களை மறைப்பதில் சூரியனாகவும், தீய வாதிகள் என்னும் யானைகளின் குதர்க்கம் என்னும் மத்தகத்தைப் பிளப்பதில் சிறந்த சிங்கமாகவும், ஆர்வமுள்ள மக்களின் கண்கள் என்னும் அல்லிகளை மகிழ்விப்பதில் சந்திரனாகவும், சபை வட்டத்தின் அணிகலனான உடலுடையவராகவும் ஆனந்ததீர்த்தர் விளங்கினார்.',
        '0.52': 'இவ்வாறு கவிகுலத் திலகரான த்ரிவிக்ரம பண்டிதாசாரியரின் மகன் நாராயண பண்டிதாசாரியர் இயற்றிய, “ஆனந்த” என்ற முத்திரை கொண்ட ஸ்ரீமத் ஸுமத்வ விஜய மகாகாவியத்தின் ஐந்தாம் சர்க்கம் நிறைவுற்றது.',
      },
    },
    'sumadhva-vijaya-06': {
      verses: {
        '0.0': 'பிறகு அங்கிருந்த சபையில் ஒரு மூத்தவர் ஐதரேயத்தின் ஒரு சூக்தத்தைச் சுட்டிக்காட்டி, “தங்களிடமிருந்து இந்தச் சூக்தத்தின் பொருளைக் கேட்கச் சபை விரும்புகிறது” என்றார்.',
        '0.1': 'எழுத்துகளின் செம்மையால் கம்பீரமான, அவசரமில்லாத, சம மாத்திரைகள் கொண்ட, சரியான இலக்கணங்கள் கொண்ட, மேக முழக்கம் போல் இதயத்தைக் கவரும் உச்சரிப்புடன் அதை ஓதி, அவர் பொருளைக் கூறினார்.',
        '0.2': 'இந்த ஓதலின் இலக்கணத் தூய்மையில் அவர் தேவகுரு பிருஹஸ்பதியையும் விஞ்சுகிறார் என்று அவர்கள் மனதில் ஏற்றுக்கொண்டாலும், அந்தச் சூக்தத்திற்கு வேறு பொருள் உண்டு என்று கூறினர்.',
        '0.3': 'அவர் கூறினார்: “அப்படியும் இருக்கலாம்; இந்தப் பொருளும் சாத்தியமே. வேதங்களுக்கு மூன்று பொருள்கள், பாரதத்திற்குப் பத்துப் பொருள்கள், விஷ்ணு சஹஸ்ரநாமத்திற்கு நூறு பொருள்களும் உண்டு என்று அறியுங்கள்.”',
        '0.4': 'பரந்த மனமுடைய அவர் இவ்வாறு கூற, அவரை வெல்ல விரும்பிய அங்கிருந்த அந்தணர்கள் கேலிப் புன்னகையுடன், “அப்படியானால் ஹரியின் ஒரு நாமத்திற்கு நூறு பொருள்களை வர்ணியுங்கள்” என்றனர்.',
        '0.5': '“நான் அதை முழுவதும் உங்களுக்கு வர்ணிப்பேன்; நீங்கள் அதைச் சரியாகத் திருப்பிச் சொல்லுங்கள்” என்று அவர் கூற, அவர்கள் “நிச்சயமாக” என்று மிக உறுதியான முயற்சியில் இறங்கினர்.',
        '0.6': 'இலக்கண சாஸ்திரம் விதித்த பகுதி, விகுதி சேர்க்கை முறைகளைக் காட்டி, தூய அறிவாளர் நூற்றுக்கணக்கான உபநிஷத் வாக்கியங்களால் நிறுவப்பட்ட “விஸ்வ” என்ற நாமத்தின் பொருள்களை உடனே கூறினார்.',
        '0.7': 'அச்சமின்றி இடைவிடாமல் பேசி அவர் நூறு பொருள்களை முடிப்பதற்குள், வர்ணிக்கப்பட்டதை நினைவில் வைக்க இயலாத அவர்கள் கலங்கிப் போயினர்.',
        '0.8': 'அங்கங்களுடன் வேதங்களில் வல்லவர்களும், இதிகாசங்களில் பயின்றவர்களும், மிகத் துணிவுள்ளவர்களுமான பலர் இருந்தும், பிரளய நீரைக் கிணறுகள் தாங்க முடியாதது போல், அவர் சொன்னதை அவர்களால் கிரகிக்க முடியவில்லை.',
        '0.9': '“உங்கள் மேதை தேவர்களிடமும் அரிது; நிலையற்ற மனிதர்களைப் பற்றிச் சொல்வதென்ன? அமைதியானவரே, எல்லாம் அறிந்தவரே, மன்னியுங்கள்; உங்களுக்கு வணக்கம்” என்று கூறி அவர்கள் அவரை வணங்கினர்.',
        '0.10': 'பிறகு பரந்த மனமுடைய அவர், வேத சாஸ்திரங்களில் வல்லவர்களும் கல்விச் செல்வத்தை விரும்பியவர்களுமான கேரளத்தின் அழகிய பகுதியில் பிறந்த அனைவருடனும் சேர்ந்து வேறொரு கோயிலை அடைந்தார்.',
        '0.11': '“ஐயோ, இவர் தர்க்க சாஸ்திரத்தில் வல்லவர்களையும் மீண்டும் மீண்டும் செருக்கிழக்கச் செய்கிறார்; இங்கே கூடியிருக்கும் இந்த நாட்டவரான நம் செருக்கை எப்படி அடக்காமல் இருப்பார்?”',
        '0.12': 'இவ்வாறு ஆலோசித்து, வேறு நாட்டவர்களைத் தலைவர்களாகக் கொண்ட அந்தச் சிறந்த அந்தணர்கள் அவரை அணுகி, கொடையாளியைப் புகழ்ந்து கஞ்சனை இகழும் சூக்தத்தின் பொருளைக் கேட்டனர்.',
        '0.13': 'அதைத் தெளிவாக்கி, “ப்ருணீயாத்” என்ற சொல்லுக்கு “ப்ருண்” என்ற தாதுவே மூலம் என்று அவர் கூறினார்; பின் வெல்ல விரும்பி “ப்ரீ” தாது என்று சொன்ன அந்தணரிடம் அவர் கூறினார்:',
        '0.14': '“‘ப்ர’ முதலிய உபசர்க்கங்களின் வேறுபாட்டையும் அறியாத மூடனே, மண்ணில் எழுத்துக்களை எழுதிப் பயிற்சி செய்!” என்று கடிந்து, பொறாமையால் கலங்கியவர்களைத் திகைக்கச் செய்து அந்த இனிய சிரிப்பாளர் சிரித்தார்.',
        '0.15': 'அந்த நிகழ்வின் மூலம் அந்தப் பரந்த இதயத்தவரின் எல்லாக் கல்வித் திறமையையும் உணர்ந்து, தேவர் கூட்டங்கள் எவரை வணங்குகின்றனவோ அவரை அவர்கள் மிகுந்த மரியாதையுடன் வணங்கினர்.',
        '0.16': 'ஒரு சபையில், இந்திரனால் மதிக்கப்பட்ட ஒரு கன்னிக்கு உடல் அழகு அளித்ததைக் கூறும் சிறந்த சூக்தத்தின் கருத்தை விளக்கியபோது, “அபாலா” என்பதற்கு “மிக இளம் பெண்” என்று அவர் கூறினார்.',
        '0.17': 'அங்கிருந்த ஓர் அறிஞர் அந்தச் சொல்லுக்கு “வெண்குஷ்டம் உள்ளவள்” என்பதே பொருள் என்று பிடிவாதமாகக் கூற, “ஓர் அறிஞர் இங்கே வருவார், அவரைக் கேளுங்கள்” என்று சொல்லி அவர் சென்றுவிட்டார்.',
        '0.18': 'விரைவிலேயே அதே போன்ற தோற்றமுடைய ஓர் அறிஞர் அந்த நாட்டுக்கு வந்து, வியப்பூட்டும் வகையில், அறிஞர்களின் முடிமணி சொன்னபடியே அந்தச் சொல்லின் பொருளை அவர்களுக்குக் கூறினார்.',
        '0.19': 'அவருக்கு எல்லா வேதக் கல்வியும், பிரமாணத்தை அடிப்படையாகக் கொண்ட எல்லாச் சொற்களும் மட்டுமல்ல, கடந்ததும் வருவதுமான ஞானமும் உண்டு என்று அந்தப் பரந்த மனத்தோர் நம்பினர்.',
        '0.20': 'உடனே எந்த எந்த விஷயம் எழுப்பப்பட்டாலும் அவர் அதை முழுமையாக அறிந்திருந்ததால், எல்லா அறிஞர்களின் சபையிலும் எப்போதும் “சர்வஞ்ஞ யதி” என்று புகழ்பெற்றார்.',
        '0.21': 'முழுநிலவு நிலவொளியால் எங்கும் பரவுவது போல், நல்லோராகிய அல்லிகளின் நண்பரான பூர்ணப்ரஜ்ஞர் தாம் செல்லாத நாடுகள் அனைத்திலும் தம் பரந்த புகழால் நிறைந்தார்.',
        '0.22': 'அழகிய பல கோயில்களில் இந்திரா ரமணனுக்கு வணக்கம் செலுத்தியவாறு, நல்ல சிந்தனையாளரான அவர் விரைவில் ரௌப்யபீடபதியான முகுந்தனை (உடுப்பியை) அடைந்தார்.',
        '0.23': 'அங்கே அவர் வேதத்தை (திரௌபதியைப் போல்) ஒரு சிறந்த பெண்ணின் வடிவில் கண்டார்: சிறந்த அந்தணர்களின் அறிவுச் செழிப்பால் வெளிப்பட்ட உடலுடையவள், அழகிய அங்கங்கள் கொண்டவள், சூத்திரங்கள் (நூல்கள்) என்னும் ஒளிரும் ரத்தின மாலையால் அலங்கரிக்கப்பட்டவள், உலகங்களின் அணிகலன் —',
        '0.24': '— அழகிய பாதம், பதம், கிரமம் (அடிகள்) ஆகியவற்றால் விளங்குபவள், தெளிவான எழுத்துகளும் குணங்களும் நிறைந்தவள், சிறந்த பாரதத்தைத் தாங்குவோருக்கு ஏற்ற ஆடை அணிந்தவள், ஸ்வரங்களின் சிறப்பழகு கொண்டவள் —',
        '0.25': '— ராஜசூயம் முதலிய பெரும் யாகங்களில் ஈடுபட்டவள், வாசுதேவனின் குணங்களில் நிலைத்த உள்ளம் கொண்டவள், எல்லா தர்மங்களையும் கற்பிப்பதில் வல்லவள், மக்களால் தாயைப் போல் வணங்கப்படுபவள் —',
        '0.26': '— நியாய வழியைக் கைவிட்டுத் தன் ஈஸ்வரத்தன்மையையே நிறுவ முயன்ற மாயைக்காரனான ஒரு தீயவனால் சபையில் கூந்தலை (உபநிஷத்துக்களை) பற்றி இழுக்கப்பட்டுத் துயருற்றவள் —',
        '0.27': '— கலியின் வலிமையால் நல்வழியிலிருந்து விலகிய, மிக எளியோரான சில நல்லோராலும் புறக்கணிக்கப்பட்ட இழுப்புத் துயருடையவள், சிலரால் பெரும் துயருடன் பார்க்கப்பட்டவள் —',
        '0.28': '— “வாசுதேவா, தரணீதரா, நாதா” என்று உரக்க மீண்டும் மீண்டும் கதறியவள், ஆறு குணங்களும் நிறைந்தவனும் பிறப்பற்றவனும் குற்றமற்றவனும் அனைத்திலிருந்தும் வேறானவனுமானவனை இதயத்தில் தாங்கியவள் —',
        '0.29': '— “அறிஞர்கள் இதைத் தடுக்கட்டும்; ஐயோ ஐயோ, இது தர்மம் அல்ல!” என்று கூறியவள், கிருஷ்ணனால் மிகவும் கொஞ்சப்பட்டவள், குற்றமற்றவள், வேறு புகலிடமின்றி அடைக்கலத்தை ஏங்கியவள் (என வேதத் தாயைக் கண்டார்).',
        '0.30': 'முன்பு பரதர்களில் சிறந்த பீமன் வேள்வித் தீயில் பிறந்த திரௌபதியைக் கண்டது போல், வேதத் தொகுதியைத் தாமே அந்நிலையில் கண்டு, உறுதியான மனமுடைய கருணைக் கடல் தீய தரப்பை அடக்கும் உறுதியான சபதம் செய்தார்.',
        '0.31': 'எவ்வளவு அனுபவித்தாலும் குறையாத சிறந்த செல்வம் போன்ற ஞானத்தைத் தொலைவு வரை பரப்ப விரும்பி, அவர் ஹரிகீதா பாஷ்யத்தை (கீதா பாஷ்யத்தை) இயற்றி மூத்த குருவுக்கு அர்ப்பணித்தார்.',
        '0.32': 'பரந்த அறிவுடைய அந்த தர்க்கவாதி தீர்த்த யாத்திரை செல்ல அனுமதி கேட்டபோது, புருஷோத்தமதீர்த்தர் (அச்யுதப்ரேக்ஷர்) புருஷோத்தமனின் காப்பை எண்ணி அனுமதி அளித்தார்.',
        '0.33': 'மலய மலையின் நறுமணத் தென்றலைப் போல் — தூசியற்றவராக (ரஜோகுணமற்றவராக), பூமியில் போற்றப்பட்டவராக, எப்போதும் வண்டுகளால் (சீடர்களால்) பின்தொடரப்பட்டவராக, நல்ல வழிப்போக்கரின் வெப்பத்தைப் போக்கியவாறு — வாயுவின் அம்சமான அவர் வடக்குத் திசை நோக்கிப் புறப்பட்டார்.',
        '0.34': 'அறிவைத் தூய்மையாக்கும் சொற்கள் (கதிர்கள்) நிறைந்த, பூமியிலுள்ள இரு வகைத் தீர்த்தங்களையும் (புனித நீர்களையும் குருமார்களையும்) அந்தக் கூர்மதியாளர் தாம் மூழ்குவதாலேயே நன்கு தூய்மைப்படுத்தினார்.',
        '0.35': 'எப்போதும் வாசுதேவனின் திருவடிகளைச் சார்ந்தவரும், ஒளியால் சிவனையும் மிஞ்சியவரும், பாவம் போக்கும் புகழ் கொண்டவருமான அவர், கங்கைப் பெருக்கையும் பெரிதும் விஞ்சினார்.',
        '0.36': 'ஆங்காங்கே சஞ்சரித்து, நினைத்த மாத்திரத்தில் இன்பம் தரும், மூவுலகையும் வியக்கச் செய்யும் செயல்களைச் செய்தவாறு, மனிதர்களுக்கு அணுகக்கூடிய பதரிகாசிரமத்தின் அருகே அவர் சேர்ந்தார்.',
        '0.37': 'முழு பாரத கண்டத்தையும் அலங்கரித்து இங்கே நாராயணன் என்று புகழ்பெற்ற பரம்பொருளை வணங்கி, பேரறிவாளர் கீதா பாஷ்யத்தை அவனுக்குக் காணிக்கையாக அர்ப்பணித்தார்.',
        '0.38': 'அவன் மகிழ்ச்சிக்காக மக்களை அகற்றிவிட்டு அவன் முன் சிறந்த பாஷ்யத்தை வாசித்தவாறு, “உருக்ரமனின் (கிருஷ்ணனின்) கீதையின் பொருளை என் சக்திக்கேற்பக் கூறுகிறேன்” என்று பூர்ணப்ரஜ்ஞர் கூறினார்.',
        '0.39': 'உலகின் தந்தை கூறினான்: “இதன் நுண்பொருளையும் முழுப் பொருளையும் சொல்ல நீ வல்லவனே; நீ அனைத்தையும் சொல்லாததால், இங்கே ‘சக்தித:’ என்பதற்குப் பதில் ‘லேசத:’ (ஒரு பகுதியாக) என்ற சொல் இருக்க வேண்டும்.”',
        '0.40': 'அந்த இறைவன் இவ்வாறு உரைக்க, உறங்கிக்கொண்டிருந்த சீடர்களும் அதைக் கேட்டனர் — “அப்படியே சொல்லப்படட்டும்” என்று ஹரி தரையைத் தட்டியவாறு மீண்டும் மீண்டும் சொன்ன சொல்லை.',
        '0.41': 'அர்ச்சா வடிவில் அமர்ந்திருந்த பரம்பொருள் செய்த அந்தச் சொல் மாற்றத்தை உணர்ந்து, அவன் கருத்தை அறிந்த பேரறிவாளர் எழுந்து சீடர்களுக்கு அதை விளக்கினார்.',
        '0.42': 'பனிக்கு அஞ்சி மனிதர்கள் தொடாத குளிர்ந்த கங்கை நீரில் அவர் தினமும் அருணோதய வேளையில் நீராடினார்; ஏனெனில் அவர் வாயுதேவரின் அம்சம்.',
        '0.43': 'தூய இதயமுடையவராக இருந்தும், எப்போதும் மகிழ்ந்திருக்கும் ஹரியின் சிறப்பு மகிழ்ச்சியை நாடி, அவர் கடுமையான மௌனத்தையும் முழு உபவாசத்தையும் கடைப்பிடித்து, அனந்த மடத்தில் இறைவனைத் தியானித்தார்.',
        '0.44': 'அங்கே ஒரு மண்டல காலம் கழிந்ததும், பிறருக்கு ஒளியைக் கண்டதாலேயே தன் வருகை தெரியும்படி இருந்த முகுந்தன், தன் திருவடிகளில் மனம் ஈடுபட்ட மத்வரைத் தன் ஆசிரமத்திற்கு வரும்படி தூண்டினான்.',
        '0.45': 'பகவான் இரவிலேயே வந்திருந்தான்; ஆயிரம் கதிர்களுடைய சூரியன் உதித்ததும், மௌனமாக இருந்த, உயர்ந்த உள்ளமுடைய, சீடர்களுக்குக் கற்பிப்பதில் ஈடுபட்ட அந்தக் கருணையாளர் இவ்வாறு எழுதினார்:',
        '0.46': '“இதைப் போன்ற பாவம் போக்கும் இடம் இல்லை; இந்தத் தீர்த்த நீருக்கு இணையான நீர் இல்லை; விஷ்ணுவுக்கு இணையான தெய்வம் இல்லை; எங்கள் உபதேசத்திற்கு இணையான நன்மை இல்லை.”',
        '0.47': '“இந்த நபர் வியாசரூபியான அஜிதனைக் காண விரும்பி இப்போதே செல்கிறார்; இங்கே திரும்பி வருவாரோ இல்லையோ, அவனே அறிவான்; உங்களுக்கு நலம் உண்டாகட்டும்” என்று எழுதி மத்வர் புறப்பட்டார்.',
        '0.48': '“நாதா, நாதா, ஐயோ! இங்கே தலைவனற்ற எங்களை விட்டுவிடாதீர்கள்; பகவானே, நீங்கள் பெருங்கருணையாளர்” என்று சீடர்கள் மனதில் எண்ணினாலும், தலைவரின் விருப்பத்தை மீறுவோமோ என்ற அச்சத்தால் சொல்லவில்லை.',
        '0.49': 'நல்ல குருவின் பிரிவைத் தாங்க முடியாமல், பூர்ணப்ரஜ்ஞரிடமிருந்து ஐதரேய சாகைகளின் சிறந்த பொருளை மூன்று முறை கேட்டிருந்த சத்யதீர்த்த யதி அவரைப் பின்தொடர்ந்தார்.',
        '0.50': 'கடினமான வழியில் பின்னால் ஓடியும், சூரியன் சிவக்கும் வேளையில், பள்ளத்தாக்குகளுக்கு அப்பால் வெகு தொலைவிலிருந்த பாறைகளின் மேல் விளையாட்டாக வேகமாக அடியெடுத்து வைத்த அவரை அவர் அடைய முடியவில்லை.',
        '0.51': 'திரும்பாமலேயே தொலைவிலிருந்து கை அசைவால் குரு தூண்ட, அஞ்சிய அவர் அன்று குரு கடந்திருந்த வழி முழுவதையும் ஒரு கணத்தில் கடந்தார்.',
        '0.52': 'அங்குள்ள ஆசிரமத்தில் தம்மவர்களைக் கண்டு, குருவின் அந்த அருள் மகிமையையும் மிக வியப்பான அந்தத் தாவலையும் கூறி, அவர்களுடன் அதை எப்போதும் நினைவுகூர்ந்தார்.',
        '0.53': 'வானரவேந்தன் ஹனுமானைப் போல் வாயு வேகம் கொண்டவரும், பீமசேனனைப் போல் தானவர்களுக்கு அச்சமூட்டுபவரும், பெயரே பாவத்தை அழிப்பதுமான அவர் மலையரசின் சிகரத்தில் சென்றவாறு விளங்கினார்.',
        '0.54': 'மேலே சென்றவாறு, அச்சமின்றி விரிந்த கண்களுடன் அவர் பல உயிரினங்களும் பறவைகளும் நிறைந்த, கடினமான, பெரும் பனி கொண்ட மாபெரும் இமயமலையைக் கண்டார் (இச்செய்யுள் யமக அணியால் அமைந்தது).',
        '0.55': 'அந்த மலை நேரே பகவானைப் போலவே தோன்றியது: புன்னகைக்கும் தாமரைக் குளங்களால் (கமலையால்) தழுவப்பட்டது, நல்லோரின் இன்பத்திற்காக அனந்தனின் படுக்கை போல் பரந்தது, உயர்ந்தது, மலர்ந்த பூங்கொத்துகள் கொண்டது, மரகத ரத்தினம் போன்ற சரிவுகளால் ஒளிர்வது —',
        '0.56': '— அடிவாரத்தில் வணங்கும் மாமுனிவர் கூட்டங்கள் கொண்டது, பொன்போல் ஒளிரும் வானமே ஆடையாகக் கொண்டது, ரத்தினக் கூட்டங்களாலும் பொன் சரிவுகள் என்னும் கடகங்களாலும் விளங்குவது, வனமாலையால் அழகியது — அந்த “தரணீதரனை”க் கண்டு, ஆனந்ததீர்த்தர் ஆனந்த வடிவான முராரியை நினைவுகூர்ந்தார்.',
        '0.57': 'இவ்வாறு கவிகுலத் திலகரான த்ரிவிக்ரம பண்டிதாசாரியரின் மகன் நாராயண பண்டிதாசாரியர் இயற்றிய, “ஆனந்த” என்ற முத்திரை கொண்ட ஸ்ரீமத் ஸுமத்வ விஜய மகாகாவியத்தின் ஆறாம் சர்க்கம் நிறைவுற்றது.',
      },
    },
    'sumadhva-vijaya-07': {
      verses: {
        '0.0': 'பிறகு இமயத்தின் மற்றொரு சரிவில், பதரி மரங்களின் சிறப்புத் தோப்பால் அலங்கரிக்கப்பட்ட, ஸ்ரீயின் இருப்பிடமான, புகழ்பெற்ற பரம ஆசிரமத்தை அந்தச் சர்வஞ்ஞர் கண்டார்.',
        '0.1': 'அங்கே இரண்டும் ஒரே போல் விளங்கின — விந்தையான மரங்களும் அந்தணர்களும்: பனி, மழை, சூரிய வெப்பத்தைத் தாங்குபவை, பரந்த நிழலால் (பெரும் யாகங்களால்) புகழ்பெற்றவை, பறவைகளுக்கு (த்விஜர்களுக்கு) அடைக்கலமானவை, வானத்தை (விஷ்ணுவின் திருவடியை) தொடுபவை.',
        '0.2': 'அது செவிக்கு அமுதம் போன்ற பாடல்களுடைய கிளிகள் முதலிய நல்ல பறவைகளாலும் (சுகர் முதலிய முனிவர்களாலும்), கமலைக்கு மிக அன்பான, நிலையான உள்ளம் கொண்ட, தூய சிறந்த அன்னங்களாலும் (பரமஹம்ஸர்களாலும்) நிறைந்திருந்தது.',
        '0.3': 'மலர்க் குவியல்களால் (நல்லுள்ளத்தோரால்) நிறைந்த, மனம் விரும்பியதை அருளும், சிறியோருக்கு அணுக முடியாத, ஒன்றுக்கொன்று பகையற்ற உயிர்கள் கொண்ட அந்த ஆசிரமம் அச்யுதனின் இருப்பிடமான வைகுண்டம் போலவே இருந்தது.',
        '0.4': 'முப்பத்திரண்டு சிறந்த லக்ஷணங்கள் கொண்ட அவர் அந்த ஆசிரமத்தில் நுழைவதைக் கண்டு, குணங்களின் சாரத்தை அறிந்த முனிவர்கள் ஆர்வத்துடன் இவ்வாறு எண்ணினர்:',
        '0.5': '“ஒப்பற்ற பொன் பனைமரம் போன்றவரும், தாமரைக் கண்ணரும், தூய நிலவு போன்ற முகமுடையவரும், யானையரசின் நடையுடையவரும், பெருந்தோளரும், இங்கே வருபவருமான இந்த அரிய மனிதர் யார்?”',
        '0.6': '“சந்திரன் மிக அமைதியான உடல் மட்டுமே உடையவன், சூரியன் முழுதும் கடுமையானவன்; ஆகவே குணக் கடல் வடிவான இவருக்கு உலகங்களில் உவமை கிடைப்பதில்லை.”',
        '0.7': '“களைப்பற்ற இந்த உறுதியான அறிவாளர் பரமஹம்ஸர்களின் அடையாளங்களைத் தாங்கியுள்ளார்; மனித வடிவில் இருந்தும் நமக்குப் பெரும் வியப்பை உண்டாக்குகிறார்.”',
        '0.8': '“வேதங்களின் நாதனைக் காண விரும்பி யதி வடிவில் வரும் இவர் நான்முகப் பிரம்மனோ அல்லது வாயுவோ ஆக வேண்டும்; இல்லையெனில் எல்லாவற்றிலும் சிறந்த லக்ஷணங்கள் உடையவராக இருக்க முடியாது.”',
        '0.9': 'ஆர்வமுற்ற அவர்கள் லக்ஷணங்களைக் கண்டு இவ்வாறு எண்ணிக்கொண்டிருக்க, தாமதமின்றி நடந்த அவர் அருகே தேவ மரங்களில் சிறந்த ஒரு மரத்தைக் கண்டார் —',
        '0.10': '— வழவழப்பான பட்டையும், உயரமும், விரிவும் கொண்டு, பல கிளைகளே படங்களாகவும் பூக்களே ரத்தினங்களாகவும் இருந்த — இறைவனின் சேவைக்காக அருகே நின்ற பகவான் அனந்தனைப் (சேஷனைப்) போல.',
        '0.11': 'மிக விந்தையான இலைகள் (இறகுகள்) கொண்ட, பல நிறமுள்ள, சூரியக் கதிர்களை (பாம்புகளை) தடுக்கும், முனிவர்களை மகிழ்விக்கும், இந்திராபதிக்கு மிக அன்பான அந்த மரம் பறவையரசன் கருடனைப் போல இருந்தது.',
        '0.12': 'அமுத வடிவான பெரும் பழத்தை அளிப்பதும், ஹரி பக்தியற்றோருக்குக் கிடைக்க அரிதானதும், நல்ல புராணங்களையும் பாரதத்தையும் சார்ந்ததும், பல கிளைகள் (சாகைகள்) கொண்டதுமான அந்த மரம் உருவெடுத்த வேதம் போல இருந்தது.',
        '0.13': 'பிறகு அதன் மிக அகன்ற, தூய, அழகிய மேடையில், வானில் தேவர்களைப் போல் சிறந்த தவசிகளை அந்த அளவற்ற அறிவாளர் கண்டார்.',
        '0.14': '— ஏழேழு குழுக்களாக விளங்கியவர்கள், எண்ணற்றவர்கள், குணமுடையோராயினும் முக்குணங்களுக்கு அப்பாற்பட்டவர்கள், கோபம், செருக்கு முதலியவை அற்றவர்கள், போகமற்றவர்கள், எப்போதும் காற்றையே உணவாகக் கொண்டவர்கள்.',
        '0.15': 'அங்கே முனிவர் வட்டத்தின் நடுவே இருந்த, மூவுலக வட்டத்தின் அணிகலனான சத்யவதியின் மைந்தனான ஹரியை (வியாசரை) பூர்ணப்ரஜ்ஞர் கண்டார்.',
        '0.16': 'தம் மிகத் தூய இதயத் தாமரையில் அவனை எப்போதும் நன்கு கண்டிருந்தும், இப்போது மீண்டும் மீண்டும் புதிதாகக் கண்டு அவர் வியந்து இவ்வாறு எண்ணினார்:',
        '0.17': '“எண்ணற்ற குணங்களின் கடலும் தூயவனுமான இவன் நாராயணனே; விதிப்படி பராசரரிடமிருந்து சத்யவதி இவனை இங்கே பெற்றாள்.”',
        '0.18': '“நல்லோர்மீதான கருணை என்னும் பெருமலையால் கடையப்பட்ட அவன் மனம் என்னும் பாற்கடலிலிருந்து, அசுரப் பகைவனின் அன்பியான லக்ஷ்மியைப் போல், அழகிய மூன்று வேதமயமான வேதம் தோன்றியது.”',
        '0.19': '“இதே கடலிலிருந்து புராணங்கள் என்னும் வெண்ணிறக் காமதேனுவும் மகாபாரதம் என்னும் பாரிஜாதமும் பிறந்தபின், சிறந்த சூத்திரத் தொகுதி என்னும் அமுதம் தானாகவே தோன்றியது.”',
        '0.20': '“பாண்டுவின் மைந்தர்கள் முதலிய நல்லோர்மீது தடையற்ற பேரருளைப் பொழிந்து, இனிய சொல்லுடைய இவன் ஞானத்தைக் காக்க நெடுங்காலம் பூமியில் சஞ்சரித்தான்.”',
        '0.21': '“இப்போது கலிகாலம் நடப்பதற்காக — இரவு வர வேண்டிச் சூரியன் மறைவது போல் — பகவான் இந்த ஆசிரமத்தில் வாழ்ந்தவாறு மக்களின் கண்களுக்குத் தெரிவதை விட்டுவிட்டான்.”',
        '0.22': '“மலர்ந்த நீலத் தாமரை போன்ற அழகிய ஒளியுடைய, சிறந்த மான்தோல் யோகபீடத்தில் அமர்ந்த, என் மனத்துக்கும் கண்களுக்கும் மகிழ்ச்சி தரும் அவனுடைய இந்தத் திருமேனி இங்கே காணப்படுகிறது.”',
        '0.23': '“எண்ணற்ற குணங்களால், தன் நிறைவான அளவற்ற நற்குணங்களால் நிறைந்த, எல்லாக் குறைகளும் நீங்கிய இது முற்றிலும் சத்-சித்-ஆனந்த மயமானதே.”',
        '0.24': '“கமலை, தாமரையில் அமர்ந்த பிரம்மன், வாயு, கருடன், சேஷன், சிவன், இந்திரன் முதலானோர் இவனுடைய திருவடித் தாமரையின் தூசியைத் தலையில் தாங்குகின்றனர்; ஆஹா, நானும் அதை மீண்டும் மீண்டும் தாங்குகிறேன்!”',
        '0.25': '“கொடி, வஜ்ரம், அங்குசம், தாமரை ஆகிய அடையாளங்கள் கொண்ட, இயல்பாகச் சிவந்திருந்தும் பக்தர்களின் உள்ளத்து அன்பை அழுத்துவதால் சிவந்தது போன்ற இறைவனின் இரு திருவடிகளையும் வணங்குகிறேன்.”',
        '0.26': '“விஷ்ணுவின் திருவடியையே சார்ந்த (சூரியன் வானைச் சார்ந்திருப்பது போல்), தம் ஒளியால் வெளி, உள் என்ற இரு இருள்களையும் அழிக்கும் இவனுடைய நகங்கள் புதிதாக உதித்த சூரியனையும் வெல்கின்றன.”',
        '0.27': '“மென்மையான உள்ளங்கால்களும் விரல்களும் மறைந்த கணுக்கால்களும் கொண்ட இவனுடைய பாதங்களுக்கு, ஒன்றுக்கொன்று தவிர வேறு உவமையைச் சிறந்த கவிஞர்களும் காண்பதில்லை.”',
        '0.28': '“தகுந்த கனத்தை (பெருமையை) கொண்ட, படிப்படியாகச் சிறுத்துச் செல்லும், தூய, ஒளிமிக்க, நன்கு உருண்ட (நல்லொழுக்கமுள்ள) இறைவனின் இந்தக் கணைக்கால் இணை, வழிபடுவோருக்குத் தன்னைப் போன்ற வடிவை அருள்கிறது.”',
        '0.29': '“அசையாத ஆசனத்தைக் கட்டும் யோகபட்டிகை என்னும் சிறந்த அரைக்கச்சை, ஒருமுறை அடைந்தால் விரும்பியதை அருளும் ஹரியைச் சுற்றிலும் இடைவிடாமல் தழுவுகிறது; அது மிகப் பாக்கியமானது என்பது என் கருத்து.”',
        '0.30': '“அழகிய ஒளியால் மின்னும், அகன்ற சிறந்த இடுப்பைச் சூழ்ந்த அழகிய சிறந்த மான்தோலால் அவன் மிக வியப்பாக விளங்குகிறான்.”',
        '0.31': '“மெல்லிய, ஆழ்ந்த அழகிய நாபியால் விளங்கும், மடிப்புகள் கொண்ட, மிக அழகிய, மென்மையான இந்த வயிற்றில் பத்மநாபன் பிரம்மாண்ட மண்டலம் முழுவதையும் தாங்கியுள்ளான்.”',
        '0.32': '“நல்லோரின் உயர்வுக்குக் காரணமான அகன்ற மார்பில், முனிகுலத்தின் முடிமணி இரண்டைத் தாங்குகிறான்: மூன்று வேதமயமான தூய பூணூலும், சிறந்த பிரம்மசூத்திரமும் (சொல்லின் இரு பொருளிலும்).”',
        '0.33': '“இணையற்ற, மேலானவர் இல்லாத தன் தந்தையான இறைவனுக்கு, பிரம்மன் சூரியக் கூட்டத்தின் ஒளியுடைய, மூவுலக வெற்றிக் கொடியான, கழுத்தில் அணிந்த இந்த அணிகலனை அர்ப்பணித்தான்.”',
        '0.34': '“சக்கரம், தாமரை ஆகிய அடையாளங்களால் ஒளிரும் மென்மையான சிவந்த கைத்தாமரைகளுக்கும், அகன்று பருத்து உருண்ட கைகளுக்கும் நாம் உவமையே காணோம்.”',
        '0.35': '“சிறந்த ஞான முத்திரையில் உள்ள இறைவனின் ஒரு கை வழிபடுவோரின் அறியாமையை அறுக்கிறது; முழங்கால்மேல் வைத்த மற்றொரு கை பெரும் அச்சத்தை அழித்த மிக மங்களமானது.”',
        '0.36': '“தானாகவே இடைவிடாமல் பெருகும் மூன்று வேதங்களாலேயே குறிக்கப்பட்டது போல், சங்கை வெல்லும், மூன்று அழகிய கோடுகள் கொண்ட குருவின் கழுத்து காணப்படுகிறது.”',
        '0.37': '“தேவர்களின் முடிமணியின் இந்த முகம் தன் அழகால், எல்லாக் களங்கமும் கருமையும் நீங்கிய சந்திரக் கூட்டத்தின் பெரும் எழிலையும் தாழ்த்துகிறது.”',
        '0.38': '“அவன் புன்னகைக்கும்போது சிவந்த உதடுகளின் ஒளியுடன் மின்னும் மிக அழகிய வெண்பற்களின் வரிசை, மாணிக்கத் தகடுகளின் நடுவே ஒளிரும் புதிய முத்துச் சரத்தையும் நாணச் செய்யும்.”',
        '0.39': '“ஆஹா, அந்தணர் கூட்டம் ஆர்வத்துடன் கேட்ட ஆயிரம் சிறந்த கேள்விகளுக்கு வேதநாதனின் இந்த வாக்கு ஒரே சொல்லில் பதில் அளிக்கிறது!”',
        '0.40': '“தாமரை போன்ற நீண்ட கண்களுடையவனின், உலகை மகிழ்விக்கும் புன்னகையுடன் கூடிய இந்தப் பார்வை என்னிடம் வந்து கொஞ்சி, தழுவி, என்னை நிறைவாக்குகிறது.”',
        '0.41': '“அவன் செவியருகே ஒளிரும் அன்புத் துளசி, ‘தாமரை முதலிய மலர்கள் பொறாமையால் என் நாதனின் அருகிலுள்ள என் இடத்தைப் பறிக்கக்கூடாது’ என்று கிசுகிசுப்பது போல் இருக்கிறது.”',
        '0.42': '“சிவனும் தாமரையில் பிறந்த பிரம்மனும் உட்பட உலகங்களின் படைப்பு, அழிவு, தோற்றம் முதலியவை அனைத்தும் உலகநாதனின் இந்தப் புருவங்களின் சிறு அசைவாலேயே நிகழ்கின்றன.”',
        '0.43': '“மூவுலகத் திலகமான அவனுடைய நெற்றியிலுள்ள இந்தத் திலகம், நீலமணி மலையின் உச்சியில் ஒளிரும் சிவப்புக் கற்களின் வரிசை போல் பேரழகைப் பெற்றுள்ளது.”',
        '0.44': '“சிறந்த மின்னல் வளையம் கொண்ட புதிய மேகத்தை வெல்லும், ஜடா மண்டலத்தால் அலங்கரிக்கப்பட்ட ஜகத்குருவின் திருமேனியைக் கண்டு நான் நிறைவு பெற்றேன்.”',
        '0.45': '“இடைவிடாமல் எண்ணும் ரமையும் இவனுடைய கால்விரல் நகத் தூசியில் ஒளிரும் அளவற்ற நற்குணங்களை எண்ண முடியாது; இவனுடைய மேலான குணங்களை வேறு யார் சொல்ல முடியும்?”',
        '0.46': '“ஒன்பது உறைகள் கொண்ட பிரம்மாண்டத்தையும் வீடாகவே கருதி வியப்பின்றிப் பார்த்த எனக்கு, நல்ல குருவின் இந்தத் திருமேனியைக் கண்டு வியப்பு உண்டாவது வியப்பல்ல.”',
        '0.47': 'இவ்வாறு எண்ணியவாறு வெளிப் பாதையைக் கடந்த அந்தப் பேரறிவாளர், மனத்தாலும் கண்களாலும் முன்பே அடைந்திருந்த வேதராஜனை இப்போது உடலாலும் அடைந்தார்.',
        '0.48': 'குருபக்தியின் சுமையால் வளைந்த உடலுடைய அவர் உடனே கைகூப்பி, ஒரு கணம் கண்களைப் பாதி மூடி, குருவை மட்டுமே வணங்கினார்.',
        '0.49': 'அடக்கம் என்னும் அணிகலனால் அலங்கரிக்கப்பட்டு, தெளிவான எட்டு அங்க வணக்கத்துடன், அந்தப் பாக்கியசாலியான பகவான் மிக வணக்கத்துக்குரியவனின் திருவடித் தாமரைகளில் வணங்கினார்.',
        '0.50': 'எல்லா நற்குணங்களும் கொண்ட அன்பிற்குரியவர் வணங்கியிருப்பதைக் கண்டு, பராசரரின் மைந்தன் விரைவில் நீட்டிய அழகிய இரு கைகளால் அவரை எழுப்பினான்.',
        '0.51': 'அன்பு அமுதத்தால் நிறைந்த மனமும், புன்னகை முகமும், மலர்ந்த கண்களும் கொண்ட வேதநாதன், அளவற்ற அறிவாளரை விரைவில் பற்றித் தழுவிக்கொண்டான்.',
        '0.52': 'யமனின் தங்கையான யமுனையிலிருந்து எழுந்த வலிய கருமேகம் ஜாம்பூநத நதியின் பொன்னிற நீருடன் கலந்தால், அப்போது பொன்னொளி மத்வரைத் தழுவிய நீல நிற வியாசரை அதற்கு ஒப்பிடலாம்.',
        '0.53': 'சிறந்த அந்தணக் குலங்களில் பிறந்த இந்த இரு ஹரிகளும் அரச அணிகலன்களை அணிந்திருந்தால், முன்பு அரச குலங்களில் பிறந்து ஒருவரையொருவர் தழுவிய தங்கள் முந்தைய வடிவங்களான கிருஷ்ணனுக்கும் பீமனுக்கும் தெளிவாகச் சமமாயிருப்பர்.',
        '0.54': '“உலகத் தந்தையின் தந்தையான தன் தந்தையிடமிருந்து சுகரும் இத்தகைய முழு அன்பைப் பெறவில்லை; அதை இந்தப் பாக்கியசாலி பெற்றார்!” என்று தவசிகள் பெரிதும் வியந்தனர்.',
        '0.55': 'குருவின் கருத்தை அறிந்த பண்பட்ட அவருடைய சீடர்கள், முகுந்தனின் தாசர்கள் நான்முகனுக்கு அளிப்பது போல், அடக்கத்துடன் அவருக்குத் தகுந்த ஆசனத்தை அளித்தனர்.',
        '0.56': 'சத்தியம் பேசும் சத்யவதியின் மைந்தன் “அமர்” என்று கூறித் தானும் அமர்ந்தபின், மென்புன்னகைப் பார்வைகளால் அந்த முனிவர் தலைவர்களை மதித்தவாறு அவர் அமர்ந்தார்.',
        '0.57': 'அவரைச் சிறந்தவர் என்று அறிந்த விதிகளை அறிந்த முனிவர் கூட்டங்கள் அவரை முறைப்படி மதித்தனர்; இந்த இரு கவி வேந்தர்களின் செவிக்கினிய உரையாடலைக் கேட்டுப் பேரானந்தம் அடைந்தனர்.',
        '0.58': 'நல்லோருக்காக ஆனந்தம், ஞானம் ஆகியவற்றின் வடிவங்களாகப் பூமிக்கு வந்த, வேதவியாசர், ஆனந்ததீர்த்தர் என்ற பெயர்களுடைய விஷ்ணு, வாயு என்னும் அந்த இரு தேவர்களும் அந்த ஆசிரமத்தில் சுடர்விட்டு ஒளிர்ந்தனர்.',
        '0.59': 'இவ்வாறு கவிகுலத் திலகரான த்ரிவிக்ரம பண்டிதாசாரியரின் மகன் நாராயண பண்டிதாசாரியர் இயற்றிய, “ஆனந்த” என்ற முத்திரை கொண்ட ஸ்ரீமத் ஸுமத்வ விஜய மகாகாவியத்தின் ஏழாம் சர்க்கம் நிறைவுற்றது.',
      },
    },
    'sumadhva-vijaya-08': {
      verses: {
        '0.0': 'மேதையின் ஒளி முதலிய தம் நற்குணங்களால் தவசிகளின் மனத்தைப் பெரும் வியப்பில் ஆழ்த்தியவாறு, அந்தப் பேரறிவாளர் ஒருமுறை காட்டின் தனிமையான இடத்தில் வேதநாயகனை மெதுவாக அணுகினார்.',
        '0.1': 'சேஷனைவிடச் சிறப்பாக விவரிக்கப்பட்ட அனைத்தையும் அறிபவரான இவருக்குச் சீடத்தன்மையும், பெருமனத்தவருக்குக் குருவாவது நல்லோரின் தலைவனுக்கும் பொருத்தமே என்று தேவர்கள் அந்த அணுகலை மதித்தனர்.',
        '0.2': 'முன்பே நிறைந்திருந்த மனத்தை இந்தக் கிருஷ்ணன் (வியாசர்) பரம உண்மைகளால் மீண்டும் நிரப்பினான்; முன்பிருந்தே தம் இருப்பிடமான, நகரம் போல் பரந்த பகவானின் மனத்தை மத்வர் கிரகித்தார் — இது வியப்பு!',
        '0.3': 'இதிகாசம், அழகிய புராணங்கள், சூத்திரங்கள், அன்பான பஞ்சராத்திரம் ஆகியவற்றின் உண்மைக் கருத்துடன் கூடிய, எண்ணற்ற சாஸ்திரங்களின் பரம பொருளை அந்த அளவற்ற உள்ளத்தவர் அனந்தனிடமிருந்து விரைவில் கேட்டார்.',
        '0.4': 'ருஜு கணத்தில் சிறந்த இவர் அளவற்ற பிறவிகளில் அனைத்தையும் தாமே நன்கு அறிந்திருந்தும், அரவணையில் துயில்பவன் தன் பேரருளின் வலிமையால் அவருடைய அறிவை மேலும் சிறப்பாக்கினான்.',
        '0.5': 'பிறகு பாதராயணரின் (வியாசரின்) துணையென்னும் செல்வத்துடன், அளவற்ற மனமுடைய அவர் மற்றொரு ஆசிரமத்தில் விளங்கும் நாராயணன் எனப்படும் ஹரியின் மற்றொரு வடிவை வணங்கச் சென்றார்.',
        '0.6': 'அந்தச் சிறந்த ஆசிரமத்தில், புகையின்றி எரியும் தீயைப் போல் ஒளிர்ந்த, சிறந்த மரவுரியும் முஞ்சைப் புல் அரைஞாணும் அணிந்த, ஒளிரும் ஜடா வளையமுடைய ஆதிபுருஷனை அந்தப் பேரறிவாளர் கண்டார்.',
        '0.7': 'வெல்லக் கடினமான புலனடக்கம் முதலிய தவத்துடன் எப்போதும் காட்டில் வாழ்வது போல் தோன்றினாலும், அவன் தன் இயல்பான, எதையும் சாராத, தூய, பெரும் ஆத்ம இன்பத்தில் இடையறாமல் இன்புறுகிறான்.',
        '0.8': 'தாமரையின் ஒளியையும் வெல்லும் மலர்ந்த கண்களால், அதர்மிகளுக்கு அணுக அரிதான அந்த தர்மபுத்திரனை வியப்புடன் பார்த்தவாறு, அந்தப் பரந்த மனத்தவர் மனதில் இவ்வாறு நினைத்தார்:',
        '0.9': '“நான்முகன் முதலானோருடன் பதினான்கு உலகங்களையும் பிரளயத்தில் ஆழ்த்தி, கமலையுடன் மட்டுமே ஒளிரும் பரமனான புராண புருஷன் இவனே.”',
        '0.10': '“முக்குணமயமான பிரகிருதியிலிருந்து மஹத்தையும், அதிலிருந்து மூவகை அகங்காரத்தையும், அதிலிருந்து தேவர்களையும் புலன்களையும், ஐம்பூதங்களையும், இவற்றிலிருந்து பிரம்மாண்ட மண்டலத்தையும், இங்கே உலகங்களையும் இந்தப் பகவான் படைத்தான்.”',
        '0.11': '“பிரம்மன், வாயு, கருடன், இந்திரன், சிவன் முதலிய தலைவர்களையும், பிரஜாபதிகளையும், தேவர்களையும், அவர்களைப் பின்பற்றுவோரையும், மனிதர்களையும், அசுரர்களையும் இவன் விளையாட்டாக எப்போதும் படைக்கிறான், காக்கிறான், அழிக்கிறான், அவரவர் கதியை அடையச் செய்கிறான்.”',
        '0.12': '“எண்ணற்ற நற்குணக் கூட்டமுடையவனும், குற்றமற்றவனும், உவமையாக அல்லாமல் உண்மையாகவே அனைத்தையும் தன் வசத்தில் வைத்திருப்பவனுமான இவன், தன்னவர்களின் முக்திக்காக நினைத்தல், புகழ்தல், வணங்குதல் ஆகியவற்றுக்கு உரியவனாகப் பல வடிவங்களை எடுக்கிறான்.”',
        '0.13': '“தேவர்களின் தலைவனான இந்தப் பிரபு முன்பு ஹயக்ரீவ வடிவில் வேதங்களைத் திருடிய பழைய நல்லோர் பகைவனைக் கொன்று, நான்முகனுக்கு நான்கு வேதங்களையும் கொடுத்தான்.”',
        '0.14': '“இந்திரனின் பகைவனின் (ஹிரண்யாக்ஷனின்) கை வலிமையால் இழுக்கப்பட்டு நீரில் மூழ்கிய பூமியை அவன் வராக வடிவில் தூக்கினான்; அலைகள் நிறைந்த கடலில் கூர்ம வடிவில் தன்னவர்களைக் காத்தான்.”',
        '0.15': '“அன்பர்களின் அச்சத்தை அழிக்கும் இந்த நரசிம்மன், சினம் எழுந்தபோது சக்கரம் போன்ற நகங்களின் ஒளியால் கொடியவனும் பெருவலியோனுமான தன் பகைவனை ஒரு கணத்தில் கிழித்தான்.”',
        '0.16': '“அழகிய குழந்தைப் பருவமுடைய இந்த வாமனன் தன் மேதையால் தைத்தியர்களை மயக்கி, சாக்கிட்டு இந்திரனின் பகைவனான பலியைக் கீழே அழுத்தி, தன்னவர்களுக்குப் பரம பதத்தை அளித்தான்.”',
        '0.17': '“பெரும் வல்லமையுள்ள சிறந்த தவசிகளின் குலத்தில் பிறந்து, கோடரியின் ஒளியால் செருக்குற்ற அரசர்கள் என்னும் இருளை அழித்த, உலக நன்மைக்காக இன்னொரு சூரியன் போன்ற பரசுராமனாக இவனை மீண்டும் மீண்டும் வர்ணிக்கின்றனர்.”',
        '0.18': '(இங்கிருந்து கவி சிலேடையால் ராமன், கிருஷ்ணன் ஆகியோரின் சரிதங்களை ஒன்றாகக் கூறுகிறார்.) “வசுதேவருக்கு (தேவர்களுக்கு) மகிழ்ச்சி தரும் அந்தக் கருணைக் கடலான பகவான் முன்பு சந்திர குலத்தில் (சூரிய குலத்தில்) அவதரித்தான்; திசைகளை வென்ற, கடும் வலிமையுடைய, பகைவரை அழிக்கும் தசரதன் பூமியில் அவனுடைய தந்தையானான்.”',
        '0.19': '“உலகநாதனுக்கு அன்பான நாகவேந்தன் சேஷனும் பிறந்தான்; ஒளியால் சந்திரனை வென்ற அழகிய அண்ணனை ‘ராமன்’ என்று அழைக்கின்றனர் (கிருஷ்ண கதையில் பலராமன்; ராம கதையில் லக்ஷ்மணனின் அண்ணனான ராமனே).”',
        '0.20': '“பிறகு பிரிவைத் தாங்க முடியாத தந்தையால் மீண்டும் மீண்டும் பார்க்கப்பட்டவாறு, தீயோருக்கு அஞ்சிய ஒரு தவசியால் (விஸ்வாமித்திரரால்; கம்சனிடமிருந்து விலகி வ்ரஜத்திற்கு) பிரபு காட்டுக்கு அழைத்துச் செல்லப்பட்டான்; அங்கே அவன் ஓர் அசுர இரவு அரக்கியை (தாடகையை; பூதனையை) கொன்றான்.”',
        '0.21': '“முனிவர்களின் யாகங்களுக்குப் பகைமை பூண்ட தீயோரை — போரில் கையை உயர்த்திய சுபாஹுவை (ராம கதை), கொடிய கேசி, அரிஷ்டன் முதலானோரை (கிருஷ்ண கதை) — அழித்த அவனைத் தேவர் முதலிய நல்லோர் கூட்டம் போற்றியது.”',
        '0.22': '“அவன் குணங்களைப் பாடும் பறவைகளால் (யாகத்தில் ஸ்வரத்துடன் ஓதும் அந்தணர்களால்) ஒளிரும் காட்டில் சஞ்சரித்து, கோகுலம் முழுவதற்கும் அன்பான அவன், காமமற்ற அன்புச் சுவையால் நனைந்த மனமும் சொல்லும் உடைய அழகிகளை (கோபியரை) கொஞ்சி மகிழ்ந்தான்.”',
        '0.23': '“சகோதரனுடனும் எல்லா நண்பர்களுடனும் அவன் தந்தைக்கு (ஜனகருக்கு) அன்பான இனிய நகரத்திற்கு (மதுரைக்கு; ஜனகரின் மிதிலைக்கு) சென்றான்; அதில் நுழைந்தபோது உலகின் ஒரே அழகனான அவன் ஆண் பெண்களின் கண்களுக்குப் பெருவிழாவானான்.”',
        '0.24': '“பிறகு விளையாட்டாக ஈசனின் வில்லை (கம்சனின் வில்லை) முறித்து, உக்ரசேன மன்னனின் மகனின் (கம்சனின்) வீரத்தை அழித்து, அந்தணக் குருவுக்குப் பணிவிடை செய்து, பிரம்மனின் குருவான அவன் அளவற்ற ஒளியால் தன்னவர்களை மகிழ்வித்தான்.”',
        '0.25': '“பூமிக்கு வந்த கமலையின் வடிவான, தாமரையிதழ்க் கண்ணியான அரசகுமாரியை (சீதையை; ருக்மிணியை) அவன் ஏற்றான்; தன் விளையாட்டால் பகை அரசர்களை வென்று, கடல் போல் அணுகக் கடினமான நகரை அடைந்து மகிழ்ந்தான்.”',
        '0.26': '“தாய்மாரின் மகிழ்ச்சிக்காக, நல்லோரின் விருப்பத்தை நிறைவேற்றியவாறு, மங்களமான மனைவியுடனும் பெரும் வெற்றிக் கொடியுடைய சிறந்த நண்பன் லக்ஷ்மணனுடனும் அவன் விரைவில் மகிழ்வுடன் காட்டுக்குச் சென்றான்.”',
        '0.27': '“மலைகள் முதலிய அணுகக் கடினமான இடங்களைக் கடந்து, கரன், தூஷணன் முதலிய பல நல்லோர் பகைவர்களைக் கொன்று, உலகுக்கு அச்சமூட்டிய பொறுக்க முடியாதவனைப் படிப்படியாகப் பேரிருளான நரகத்திற்கு அனுப்பினான் (நரகாசுரனைக் கொன்றான்).”',
        '0.28': '“அழகிய ஆசிரம முற்றத்தைத் தன் ஒளியால் அலங்கரித்த, உலகம் போற்றும் அன்பியுடன், செருக்கும் கவனக்குறைவும் கொண்ட தேவர்களைக் கலங்கடித்து அவர்களின் பாரிஜாதத்தைக் கொண்டுசென்ற அந்த அன்பன் தன் இருப்பிடத்தை அடைந்தான்.”',
        '0.29': '“திக்பாலர்களையும் அரச மண்டலங்களையும் பத்துத் திசைகளிலும் மீண்டும் மீண்டும் வென்ற, பிறருக்கு அச்சமூட்டிய அந்த வெறுக்கத்தக்கவன் (ராவணன்) இங்கே ஒளிர்ந்த தன் அன்பிற்குரிய ஸ்ரீயைக் கவர்ந்து செல்வதைப் பகவான் பொருட்படுத்தாமல் விட்டான்.”',
        '0.30': '“வாயுவின் மைந்தன் ஹனுமான் முதலானோரால் வணங்கப்பட்ட அவன், அம்பால் இந்திரனின் மைந்தனை (வாலியை) வீழ்த்தி, பகையற்ற அரசைத் தன் அன்பு நண்பனான சூரியனின் மைந்தன் சுக்ரீவனுக்கு அளித்தான்.”',
        '0.31': '“அங்கே வாயுமைந்தனின் வாயிலிருந்து வந்த அன்பியின் பெருஞ்செய்தியால் மகிழ்ந்த மதுசூதனன், வானரங்களின் கூர்மையான படையால் (கூர்மையான சக்கரத்தால்) விளங்கியவாறு, கடலின் நடுவே உள்ள, புண்யஜனர்களால் (அரக்கர்களால்; நல்லோரால்) நிறைந்த நகரத்திற்குச் சென்றான்.”',
        '0.32': '“கூர்மையான அம்புக் கூட்டத்தால் (கூர்மையான சக்கரத்தால்) வீரம் காட்டிய பிரபு, பூமிக்குச் சுமையாக இருந்த பெருங்கூட்டத்தை — யானையரசு போன்ற செருக்குள்ள கும்பகர்ணனை (குவலயாபீட யானையை), அவன் சகோதரனை, இந்திரனின் பகைவனை — அழித்தான்.”',
        '0.33': '“பிறகு அக்னியில் புகுந்த மனைவியுடனும், சகோதரர்கள் முன்செல்லவும், நல்லோருக்கு விருப்பத்தை அருளும் இவன் நீண்ட காலத்திற்குப் பின் தன் இருப்பிடத்தை அடைந்து தன் மூல வடிவுடன் பரம ஒருமையை அடைந்தான்.”',
        '0.34': '“மஹிதாசனாக வணங்கப்படும் திருவடிகளை உடைய அவன், புகழ்பெற்ற தூய உள்ளமுடைய விஷ்ணுயசஸ் என்ற அந்தணரிடமிருந்து (கல்கியாக) பிறந்தான்; உலகின் பாவத்தைத் தணிக்கப் பேரொளி வாளை ஏந்தி, ஒளிரும் வேதச் சொல்லின் நிலையைக் காக்கிறான்.”',
        '0.35': '“இந்தத் தேவராஜன் தவத்தால் ஒளிரும் பாவமற்ற கர்தமரிடமிருந்து மனுவின் மகள் தேவஹூதியின் மைந்தனானான் (கபிலனானான்); காலப்போக்கில் தன்மீது பக்தி நிறைந்த நல்லோரை எழுப்பினான்.”',
        '0.36': '“முழு இளமை வடிவம் வெளிப்பட்ட சிறந்த அழகியின் (மோகினியின்) உருவை எடுத்த அசுரப் பகைவனான இவன், தேவர் கூட்டத்திற்கு அமுதத்தை அளித்தான்.”',
        '0.37': '“நல்லோருக்கு நிலையை அளிப்பவனும் ஆத்மத் தூய்மையை அருள்பவனுமான இந்த நித்தியன், முனிவர் தலைவர் அத்ரியின் மனைவியான தூய மனமுடைய அனசூயையால் பேரன்புடன் சுமக்கப்பட்ட மென்மையான குழந்தையானான் (தத்தாத்ரேயனானான்).”',
        '0.38': '“நல்லோருக்கு அன்பான, பூமியை ஆண்ட இந்த ரிஷபன், பரமஹம்ஸ லக்ஷணங்கள் கொண்ட உடலைத் தாங்கி, பரம்பொருளை நாடிய சனகர் முதலானோரால் வணங்கப்பட்டு, எல்லாப் பிணைப்புகளிலிருந்தும் விடுபட்டுச் சஞ்சரித்தான்.”',
        '0.39': '“இந்த ஹரி தர்மனின் மைந்தனாக, நரனின் சகோதரனாக, உயர்ந்த வீரனாகப் பிறந்தான்; நல்லோரின் மகிழ்ச்சிக்காக ‘கிருஷ்ணன்’ எனப்படும் அவன் சகோதரனும் தானாகவே பிறந்தான்.”',
        '0.40': '“எப்போதும் ஒரே வடிவினனும், பத்து வடிவினனும், நூறாயிரம் வடிவினனும், மாற்றமற்றவனும், தெளிவாக அளவற்ற வடிவினனும், எல்லா உடல்களும் ஆனந்தமும் ஞானமுமானவனுமான பரமாத்மாவுக்கு நமோ நமஹ.”',
        '0.41': 'இவ்வாறு எண்ணியவாறு நிறைந்த இதயத்துடன் அவர் அன்புடன் ஹரியை வணங்கி அவனால் மதிக்கப்பட்டார்; ஒருவரையொருவர் மதித்து முன்பே அமர்ந்திருந்த அந்த இரு வெல்லப்படாதவர்களின் அருகே அவர் அமர்ந்தார்.',
        '0.42': 'அங்கே பல்வேறு உரையாடல்களை நடத்திய பின், உலகநாதன் (நாராயணன்) முனிவரின் மைந்தனின் (வியாசரின்) அழகிய முகத்தைப் பார்த்து, வணங்கியிருந்த மகா ஸுகதீர்த்தரிடம் தனிமையில் இந்தச் சொல்லைக் கூறினான்.',
        '0.43': '“உறுதியுள்ளவனே, தேவர்களின் பணியை மனதில் கொண்டு, மேலோர் ஏற்கும் நான் சொல்லும் இதைக் கேள்: பிறருக்கு மிகக் கடினமானதைச் செய்து உன் இந்த இளம் அவதாரம் பெரும் பலன் உடையதாகும்.”',
        '0.44': '“நல்லோருக்கு அன்பான சூத்திரங்களின் இதயத்தை மறைத்து, இப்போது தம் விருப்பப்படி பாஷ்யங்களை இயற்றி, சுருதி, ஸ்மிருதிகளின் உண்மைப் பொருளைக் கெடுக்கும் பிறரால் தாக்கப்பட்ட ஞானம் முழுவதுமாக மறைந்து வருகிறது.”',
        '0.45': '“தீயோர் செய்த இந்த அநீதியை நீக்கவும், உன்னவர்களை நல்வழிக்குத் திரும்ப அழைத்துச் செல்லவும், தாமதமின்றிச் சூத்திர பாஷ்யத்தை இயற்று; கவியே, சுருதி ஸ்மிருதிகளை உண்மைக் கொள்கையுடன் இணைப்பாயாக.”',
        '0.46': 'ஜகத்குருவின் அளவானதாயினும் அளவற்ற பொருளுடைய அந்தச் சொல்லைக் கேட்டு, நிறைந்த இதயமுடைய, அசைவன அசையாதவற்றின் தலைவர்களான அந்த இருவரின் பிரிவைத் தாங்க முடியாத சொல்வல்லோரில் சிறந்தவர் அப்போது அவர்களிடம் கூறினார்:',
        '0.47': '“பகவானே, இனி உங்கள் இருவருக்கும் இடைவிடாமல் சேவை செய்யும் அமுதத்தில் மூழ்க எனக்கு அருள் கிடைக்கட்டும்; உலகின் ஒரே மங்களமான இத்தகைய மிக அன்பான இன்பத்தை மூவுலகிலும் நான் பெற முடியாது.”',
        '0.48': '“கலிகாலத்தால் குணங்கள் விழுங்கப்பட்ட இந்தப் பூமியில் இப்போது தகுந்த அறிவுடைய நல்லவர் நிச்சயமாக இல்லை; தகுதியற்றவனுக்குப் பரம்பொருளை விவரிப்பது நாய்க்கு ஹவிஸ் அளிப்பது போல் இகழத்தக்கது.”',
        '0.49': 'இவ்வாறு கூறியவரிடம் பிரபு கூறினான்: “அமைதியானவனே, பூமியில் குணத்திற்குத் தகுந்த மக்கள் இருக்கின்றனர்; நூலில் கோக்கப்படாத தூய ரத்தினங்கள் போன்ற அவர்களைக் கருணையுடன் உன் தூய சொற்களால் (கதிர்களால்) தூய்மைப்படுத்து.”',
        '0.50': '“என் பரம ஆணையால் உன் புகழ், சூரிய ஒளி ஆந்தைகளுக்குப் போல், தீயோருக்கு மிகுந்த துன்பத்தைத் தரும்; தாமரைக் குளங்களை மலர்விப்பது போல் நல்லோரை இடைவிடாமல் விழிப்படையச் செய்யும்.”',
        '0.51': 'இவ்வாறு உலக இன்பத்திற்காகத் தரணீதரனின் வாயிலிருந்து (மலையிலிருந்து நதி போல்) பெருகிய அந்தத் தெளிந்த வாக்கு, சந்திரக் கதிர்களால் பொங்கும் கடல் போல் முன்பே நிறைந்திருந்த மத்வரின் பரந்த அறிவுக் கடலில் புகுந்தது.',
        '0.52': 'அந்த இரு மகான்களின் மதிக்கத்தக்க கருத்தை அறிந்து “அப்படியே ஆகட்டும்” என்று கூறி, அந்த உறுதியான அறிவாளர் வணங்கியவாறு, வேறு எவராலும் தாங்க முடியாத அவர்களின் ஆணையைத் தம் தலைமேல் ஏற்றார்.',
        '0.53': 'உண்மையை உணர்த்தும் மூன்று வேதங்களைப் போலவும், மக்களின் பாவத்தை அழிக்கும் மூன்று அக்னிகளைப் போலவும், அல்லது அனைத்தையும் தாங்கும் மூவுலகங்களைப் போலவும், முனிவரின் மைந்தன் வியாசர், தர்மனின் மைந்தன் நாராயணன், மத்வர் — இந்த மூவரும் அங்கே ஆனந்தத்துடன் ஒளிர்ந்தனர்.',
        '0.54': 'இவ்வாறு கவிகுலத் திலகரான த்ரிவிக்ரம பண்டிதாசாரியரின் மகன் நாராயண பண்டிதாசாரியர் இயற்றிய, “ஆனந்த” என்ற முத்திரை கொண்ட ஸ்ரீமத் ஸுமத்வ விஜய மகாகாவியத்தின் எட்டாம் சர்க்கம் நிறைவுற்றது.',
      },
    },
  },
};
